const n="todo-cli",t='status: complete\n\nnotes: All sixteen capabilities are built and working in a zero-dependency Node CLI (`bin/todo.js`, `src/`, Node 18+); `npm test` runs 67 tests that pass, covering every capability rather than just the happy paths. Tasks carry tags, priority, due date, a project, a parent, and a note; ids come from a counter persisted in the file and only ever count up, so a deleted `#3` is never handed out again. Storage is one pretty-printed JSON file resolved from `--file` → `$TODO_FILE` → `$XDG_DATA_HOME/todo/todos.json` → `~/.local/share/todo/todos.json`, and every write goes to a sibling temp file, gets `fsync`ed, then `rename`d over the target, so a crash leaves the old file or the new one and never a truncated one. Output is an aligned table that colourises only on a TTY — `NO_COLOR`, `--no-color`, `TERM=dumb`, a pipe and `--json` all switch it off, `--color`/`CLICOLOR_FORCE` force it back — and `--json` emits documented, stable field names for every command including errors, which go to stderr as `{"error":{"code":…}}`. Exit codes are 0 success / 1 actionable failure (missing id, corrupt file, declined confirmation — a clean message, never a stack trace) / 2 usage error, and a missing id among several still lets the valid ones through. `add` writes only the new id to stdout so `id=$(todo add "buy milk")` is reliable, and with no title it reads stdin for bulk add, one task per line. `delete` prompts on a terminal and refuses outright without one unless `--force`; every command has `--help` ending in worked examples. Two things worth flagging rather than burying: the bash completion is exercised for real by the test suite (sourced, driven through `COMP_WORDS`, asserted on live ids/tags/projects), but zsh and fish are not installed on this machine, so those two scripts are written to their shells\' conventions and checked structurally only — they are the least-verified part of the work. Second, the store is not locked, so two `todo` processes writing at the same instant can have one overwrite the other\'s change; each individual file is always complete and valid, which is what atomicity buys, but last-writer-wins is the concurrency model.\n',e=JSON.parse("[{\"path\":\"bin/todo.js\",\"bytes\":89,\"text\":\"#!/usr/bin/env node\\n'use strict';\\n\\nrequire('../src/cli.js').main(process.argv.slice(2));\\n\"},{\"path\":\"package.json\",\"bytes\":414,\"text\":\"{\\n  \\\"name\\\": \\\"todo-cli\\\",\\n  \\\"version\\\": \\\"1.0.0\\\",\\n  \\\"description\\\": \\\"Manage a task list from the terminal, with output humans and scripts can both read.\\\",\\n  \\\"license\\\": \\\"MIT\\\",\\n  \\\"type\\\": \\\"commonjs\\\",\\n  \\\"bin\\\": {\\n    \\\"todo\\\": \\\"bin/todo.js\\\"\\n  },\\n  \\\"files\\\": [\\n    \\\"bin\\\",\\n    \\\"src\\\",\\n    \\\"completions\\\",\\n    \\\"README.md\\\"\\n  ],\\n  \\\"scripts\\\": {\\n    \\\"test\\\": \\\"node --test \\\\\\\"test/*.test.js\\\\\\\"\\\"\\n  },\\n  \\\"engines\\\": {\\n    \\\"node\\\": \\\">=18\\\"\\n  }\\n}\\n\"},{\"path\":\"README.md\",\"bytes\":9771,\"text\":\"# todo\\n\\nA task list you drive from the terminal. Human-readable by default, and\\nscript-readable on demand — the same command with `--json` gives you stable\\nfield names, and exit codes tell a script what happened without parsing prose.\\n\\nNo dependencies. One file of JSON on disk. Node 18 or newer.\\n\\n```\\n$ todo add \\\"buy milk\\\"\\n1\\n$ todo add \\\"ship the release\\\" --due friday --priority high --tag work\\n2\\n$ todo list\\nID       PRI   DUE         TAGS  TITLE\\n 2  [ ]  high  2026-08-07  work  ship the release\\n 1  [ ]                          buy milk\\n$ todo done 2\\n[x] #2 ship the release\\n```\\n\\n## Run it\\n\\n```sh\\nnode bin/todo.js --help          # straight from this directory\\n```\\n\\nTo get a `todo` command on your `PATH`:\\n\\n```sh\\nnpm link                         # from this directory\\ntodo --help\\n```\\n\\nor make a one-line shim:\\n\\n```sh\\nprintf '#!/bin/sh\\\\nexec node \\\"%s/bin/todo.js\\\" \\\"$@\\\"\\\\n' \\\"$PWD\\\" > ~/.local/bin/todo\\nchmod +x ~/.local/bin/todo\\n```\\n\\nRun the tests with `npm test` (56 CLI/unit tests, 9 terminal-behaviour tests,\\n2 completion tests — no network, no fixtures to install).\\n\\n## Commands\\n\\n| Command | What it does |\\n| --- | --- |\\n| `todo add <title…>` | Add a task; prints the new id |\\n| `todo list` | List tasks, with filters |\\n| `todo show <id>` | Every field of one task |\\n| `todo done <id…>` | Mark complete |\\n| `todo reopen <id…>` | Mark open again |\\n| `todo edit <id>` | Change any field |\\n| `todo delete <id…>` | Delete, after confirming |\\n| `todo tags` / `todo projects` | What's in use, with counts |\\n| `todo completion <shell>` | Print a completion script |\\n| `todo help [command]` | Help, with examples |\\n\\nAliases: `ls`/`l` for `list`, `rm`/`del` for `delete`, `complete`/`do` for\\n`done`, `undone`/`undo` for `reopen`, `update` for `edit`, `view` for `show`.\\n\\nEvery command takes `--help`, and every help page ends in worked examples:\\n\\n```sh\\ntodo add --help\\ntodo help list\\n```\\n\\n### Adding\\n\\n```sh\\ntodo add \\\"buy milk\\\"                              # → 1\\ntodo add buy more milk                           # quoting is optional\\ntodo add \\\"ship it\\\" --due friday -p high -t work,urgent -P website\\ntodo add \\\"write the tests\\\" --parent 2            # a sub-task of #2\\ntodo add \\\"already did this\\\" --done\\n```\\n\\n`add` writes only the new id to stdout, so capturing it is reliable:\\n\\n```sh\\nid=$(todo add \\\"buy milk\\\")\\ntodo edit \\\"$id\\\" --due tomorrow\\n```\\n\\n**Bulk add from stdin.** With no title on the command line, `add` reads\\nstdin and makes one task per non-blank line. Any flags apply to all of them:\\n\\n```sh\\nprintf 'first\\\\nsecond\\\\n' | todo add --tag inbox\\ngit log --format=%s -10 | todo add --project changelog\\ntodo add --stdin < backlog.txt\\n```\\n\\n`--parse` opts into inline tokens, for when the line carries its own metadata:\\n\\n```sh\\ntodo add --parse \\\"fix login +bug @web !high due:friday\\\"\\n# title \\\"fix login\\\", tag bug, project web, priority high, due Friday\\n```\\n\\nWithout `--parse` a title is stored exactly as typed, so\\n`todo add \\\"email @bob about c++\\\"` keeps its `@bob`.\\n\\n### Listing and filtering\\n\\nOpen tasks only, unless you say otherwise.\\n\\n```sh\\ntodo list\\ntodo list --done                    # completed only\\ntodo list --all                     # both\\ntodo list --tag work                # repeat --tag to require several (AND)\\ntodo list --any-tag work --any-tag home     # OR\\ntodo list --due today\\ntodo list --overdue\\ntodo list --due week                # anything due in the next 7 days\\ntodo list --due before:2026-09-01\\ntodo list --priority high\\ntodo list --project website\\ntodo list --project none            # tasks with no project\\ntodo list --parent 2                # sub-tasks of #2\\ntodo list --search milk\\ntodo list --sort due --reverse --limit 5\\n```\\n\\n`--due` understands `today`, `tomorrow`, `yesterday`, `overdue`, `week`,\\n`month`, `none`, `any`, an ISO date, and `before:`/`until:`/`after:`/`since:`/`on:`\\nprefixes. Dates you set accept `today`, `tomorrow`, weekday names, `+3d`,\\n`2w`, `1m`, `eom`, `next monday`, `2026-08-31`, and `none` to clear.\\n\\nThe default order is: open before done, high priority first, soonest due\\nfirst, then id. `--sort` takes `id`, `due`, `priority`, `created`, `updated`,\\n`title`, `project` or `status`.\\n\\n### Sub-tasks and projects\\n\\nA task can hang off another (`--parent`), and any task can carry a project\\nname (`--project`). Sub-tasks are printed indented under their parent:\\n\\n```\\nID       PROJECT  TITLE\\n 2  [ ]           ship the release\\n 3  [ ]  website    - write the tests\\n```\\n\\nIf a filter matches a child but not its parent, the child is still shown —\\nat the top level, rather than hidden.\\n\\nDeleting a parent lifts its children to the top level. `--recursive` deletes\\nthe whole subtree instead. `done --recursive` and `reopen --recursive` work\\nthe same way.\\n\\n### Editing and deleting\\n\\n```sh\\ntodo edit 3 --title \\\"buy oat milk\\\"\\ntodo edit 3 --due friday --priority high\\ntodo edit 3 --add-tag urgent --remove-tag someday\\ntodo edit 3 --tag work                  # replaces all tags\\ntodo edit 3 --priority none --due none  # clear fields\\ntodo edit 3 --parent 7                  # re-parent (loops are refused)\\n\\ntodo delete 3                           # asks first\\ntodo delete 3 4 --force                 # doesn't\\n```\\n\\n`delete` asks for confirmation when it has a terminal. With no terminal —\\nin a script, a cron job, a pipeline — it refuses outright unless `--force`\\n(or `-y`) is given, rather than silently guessing.\\n\\n## Output\\n\\n**Human by default.** An aligned table, colourised when stdout is a terminal:\\noverdue dates red, today amber, high priority red, tags cyan, projects\\nmagenta, completed rows dimmed. Long titles are truncated to the terminal\\nwidth so rows never wrap.\\n\\n**Colour is off** when stdout is not a terminal, when `NO_COLOR` is set to a\\nnon-empty value, when `--no-color` is given, when `TERM=dumb`, and always in\\n`--json` mode. `--color` (or `CLICOLOR_FORCE=1`) forces it back on for\\n`less -R` and friends.\\n\\n**`--json` for machines.** Field names are stable:\\n\\n```json\\n{\\n  \\\"id\\\": 2,\\n  \\\"title\\\": \\\"ship the release\\\",\\n  \\\"done\\\": false,\\n  \\\"priority\\\": \\\"high\\\",\\n  \\\"due\\\": \\\"2026-08-07\\\",\\n  \\\"tags\\\": [\\\"work\\\"],\\n  \\\"project\\\": null,\\n  \\\"parent\\\": null,\\n  \\\"note\\\": null,\\n  \\\"created_at\\\": \\\"2026-08-03T14:01:17.392Z\\\",\\n  \\\"updated_at\\\": \\\"2026-08-03T14:01:17.393Z\\\",\\n  \\\"completed_at\\\": null\\n}\\n```\\n\\n| Command | `--json` shape |\\n| --- | --- |\\n| `list` | array of task objects |\\n| `show`, `edit` | one task object |\\n| `add` | one task object; an array when adding several |\\n| `done`, `reopen`, `delete` | array of the affected task objects |\\n| `tags` | `[{\\\"tag\\\": \\\"work\\\", \\\"count\\\": 2}]` |\\n| `projects` | `[{\\\"project\\\": \\\"acme\\\", \\\"count\\\": 1}]` |\\n| any failure | `{\\\"error\\\": {\\\"code\\\": \\\"not_found\\\", \\\"message\\\": \\\"…\\\"}}` on **stderr** |\\n\\n`priority` is `\\\"high\\\"`, `\\\"medium\\\"`, `\\\"low\\\"` or `null`. `due` is a plain\\ncalendar day, `YYYY-MM-DD` or `null` — no timezone can shift it. Timestamps\\nare UTC ISO-8601.\\n\\nThere is also `todo list --ids`, which prints bare ids for `xargs`:\\n\\n```sh\\ntodo list --ids --tag work | xargs -n1 todo done\\ntodo list --json | jq -r '.[] | select(.due != null) | .title'\\n```\\n\\n## Exit codes\\n\\n| Code | Meaning |\\n| --- | --- |\\n| `0` | it worked |\\n| `1` | it failed for a reason you can act on — no such task, unreadable or corrupt file, cancelled confirmation |\\n| `2` | you asked for something that isn't a thing — unknown command or option, bad date, bad priority |\\n\\nA missing id is a plain message on stderr and exit 1, never a stack trace.\\nWhen several ids are given, the ones that exist are still acted on and the\\nmissing ones are reported:\\n\\n```sh\\ntodo done 3 999      # completes #3, reports #999, exits 1\\n```\\n\\n## Where tasks live\\n\\nFirst of these that applies:\\n\\n1. `--file <path>`\\n2. `$TODO_FILE`\\n3. `$XDG_DATA_HOME/todo/todos.json`\\n4. `~/.local/share/todo/todos.json` (`%LOCALAPPDATA%\\\\todo\\\\todos.json` on Windows)\\n\\nThe file is JSON, pretty-printed, and safe to read, diff, commit or hand-edit:\\n\\n```json\\n{\\n  \\\"version\\\": 1,\\n  \\\"nextId\\\": 4,\\n  \\\"tasks\\\": [ … ]\\n}\\n```\\n\\nKeep separate lists side by side with `--file`:\\n\\n```sh\\ntodo --file ./project.todo.json add \\\"release notes\\\"\\ntodo --file ./project.todo.json list\\n```\\n\\n**Writes are atomic.** Every change is serialised in full to a temp file in\\nthe same directory, flushed with `fsync`, then `rename`d over the target — a\\nrename is atomic on POSIX and on Windows. A crash mid-write leaves either the\\nprevious file or the new one, never a truncated one. The temp file is cleaned\\nup if anything fails.\\n\\n**Ids are never reused.** The next id lives in the file and only ever counts\\nup, so `#3` stays `#3` in your shell history, your notes and your scripts even\\nafter tasks around it are deleted.\\n\\n## Shell completion\\n\\n```sh\\ntodo completion bash > /etc/bash_completion.d/todo\\n#   or: echo 'source <(todo completion bash)' >> ~/.bashrc\\n\\ntodo completion zsh > \\\"${fpath[1]}/_todo\\\"     # then restart the shell\\n\\ntodo completion fish > ~/.config/fish/completions/todo.fish\\n```\\n\\nCompletion covers commands, per-command options, and live data from your task\\nfile — real ids (with their titles as descriptions in zsh and fish), your\\ntags, your projects, priorities, sort keys and date words. `todo done <TAB>`\\noffers open tasks; `todo reopen <TAB>` offers completed ones.\\n\\nThe scripts are also checked into `completions/` if you would rather install\\nthem directly.\\n\\n## Layout\\n\\n```\\nbin/todo.js          entry point\\nsrc/cli.js           argument dispatch and the commands\\nsrc/args.js          option parser\\nsrc/model.js         tasks, filters, sorting, the parent/child tree\\nsrc/store.js         file location and atomic read/write\\nsrc/dates.js         date words → calendar days\\nsrc/render.js        table, colour, detail view\\nsrc/help.js          help text for every command\\ncompletions/         bash, zsh and fish completion scripts\\ntest/                node:test suites\\n```\\n\"},{\"path\":\"src/args.js\",\"bytes\":3373,\"text\":\"'use strict';\\n\\nconst { UsageError } = require('./errors.js');\\n\\n/**\\n * Minimal, predictable option parser.\\n *\\n * Supported forms:\\n *   --flag              boolean\\n *   --flag=false        explicit boolean\\n *   --opt value         value option\\n *   --opt=value         value option\\n *   -o value / -ovalue  short value option\\n *   -ab                 clustered short booleans\\n *   --                  everything after this is positional\\n *\\n * A spec entry looks like:\\n *   { type: 'boolean' | 'string' | 'array', short: 'c', arg: 'NAME', help: '…' }\\n */\\nfunction parse(argv, spec) {\\n  const flags = spec.flags || {};\\n  const shorts = Object.create(null);\\n  for (const [name, def] of Object.entries(flags)) {\\n    if (def.short) shorts[def.short] = name;\\n  }\\n\\n  const values = Object.create(null);\\n  const seen = new Set();\\n  for (const [name, def] of Object.entries(flags)) {\\n    if (def.type === 'array') values[name] = [];\\n    else if (def.type === 'boolean') values[name] = false;\\n    else values[name] = undefined;\\n  }\\n\\n  const positional = [];\\n  let rest = false;\\n\\n  const setValue = (name, def, raw) => {\\n    seen.add(name);\\n    if (def.type === 'array') {\\n      for (const part of String(raw).split(',')) {\\n        const v = part.trim();\\n        if (v) values[name].push(v);\\n      }\\n      if (values[name].length === 0 && String(raw).trim() === '') values[name].push('');\\n    } else {\\n      values[name] = raw;\\n    }\\n  };\\n\\n  for (let i = 0; i < argv.length; i++) {\\n    const arg = argv[i];\\n\\n    if (rest) { positional.push(arg); continue; }\\n    if (arg === '--') { rest = true; continue; }\\n\\n    if (arg.startsWith('--')) {\\n      let name = arg.slice(2);\\n      let inline;\\n      const eq = name.indexOf('=');\\n      if (eq !== -1) { inline = name.slice(eq + 1); name = name.slice(0, eq); }\\n      const def = flags[name];\\n      if (!def) throw new UsageError(`unknown option --${name}`);\\n\\n      if (def.type === 'boolean') {\\n        if (inline === undefined) { values[name] = true; }\\n        else if (['true', '1', 'yes', 'on'].includes(inline.toLowerCase())) values[name] = true;\\n        else if (['false', '0', 'no', 'off'].includes(inline.toLowerCase())) values[name] = false;\\n        else throw new UsageError(`option --${name} expects true or false, got \\\"${inline}\\\"`);\\n        seen.add(name);\\n      } else {\\n        if (inline === undefined) {\\n          if (i + 1 >= argv.length) throw new UsageError(`option --${name} requires a value`);\\n          inline = argv[++i];\\n        }\\n        setValue(name, def, inline);\\n      }\\n      continue;\\n    }\\n\\n    if (arg.length > 1 && arg[0] === '-' && arg !== '-') {\\n      const body = arg.slice(1);\\n      for (let j = 0; j < body.length; j++) {\\n        const ch = body[j];\\n        const name = shorts[ch];\\n        if (!name) throw new UsageError(`unknown option -${ch}`);\\n        const def = flags[name];\\n        if (def.type === 'boolean') { values[name] = true; seen.add(name); continue; }\\n        let raw = body.slice(j + 1);\\n        if (raw.startsWith('=')) raw = raw.slice(1);\\n        if (raw === '') {\\n          if (i + 1 >= argv.length) throw new UsageError(`option -${ch} requires a value`);\\n          raw = argv[++i];\\n        }\\n        setValue(name, def, raw);\\n        break;\\n      }\\n      continue;\\n    }\\n\\n    positional.push(arg);\\n  }\\n\\n  return { positional, flags: values, seen };\\n}\\n\\nmodule.exports = { parse };\\n\"},{\"path\":\"src/cli.js\",\"bytes\":25252,\"text\":\"'use strict';\\n\\nconst fs = require('fs');\\nconst path = require('path');\\n\\nconst { parse } = require('./args.js');\\nconst { UsageError, AppError, NotFoundError } = require('./errors.js');\\nconst store = require('./store.js');\\nconst model = require('./model.js');\\nconst render = require('./render.js');\\nconst help = require('./help.js');\\nconst dates = require('./dates.js');\\n\\nconst VERSION = require('../package.json').version;\\n\\n// ---------------------------------------------------------------------------\\n// Option specs\\n// ---------------------------------------------------------------------------\\n\\nconst GLOBAL_FLAGS = {\\n  file: { type: 'string', arg: 'PATH' },\\n  json: { type: 'boolean' },\\n  color: { type: 'boolean' },\\n  'no-color': { type: 'boolean' },\\n  help: { type: 'boolean', short: 'h' },\\n};\\n\\nconst g = (extra) => ({ flags: { ...GLOBAL_FLAGS, ...extra } });\\n\\nconst SPECS = {\\n  root: g({ version: { type: 'boolean', short: 'V' } }),\\n\\n  add: g({\\n    tag: { type: 'array', short: 't' },\\n    priority: { type: 'string', short: 'p' },\\n    due: { type: 'string', short: 'd' },\\n    project: { type: 'string', short: 'P' },\\n    parent: { type: 'string' },\\n    note: { type: 'string', short: 'n' },\\n    done: { type: 'boolean' },\\n    parse: { type: 'boolean' },\\n    stdin: { type: 'boolean' },\\n  }),\\n\\n  list: g({\\n    done: { type: 'boolean' },\\n    all: { type: 'boolean', short: 'a' },\\n    tag: { type: 'array', short: 't' },\\n    'any-tag': { type: 'array' },\\n    priority: { type: 'string', short: 'p' },\\n    due: { type: 'string', short: 'd' },\\n    overdue: { type: 'boolean' },\\n    project: { type: 'string', short: 'P' },\\n    parent: { type: 'string' },\\n    search: { type: 'string', short: 's' },\\n    sort: { type: 'string' },\\n    reverse: { type: 'boolean', short: 'r' },\\n    limit: { type: 'string', short: 'n' },\\n    flat: { type: 'boolean' },\\n    relative: { type: 'boolean' },\\n    ids: { type: 'boolean' },\\n  }),\\n\\n  show: g({}),\\n\\n  done: g({ recursive: { type: 'boolean' } }),\\n  reopen: g({ recursive: { type: 'boolean' } }),\\n\\n  edit: g({\\n    title: { type: 'string', short: 'm' },\\n    tag: { type: 'array', short: 't' },\\n    'add-tag': { type: 'array' },\\n    'remove-tag': { type: 'array' },\\n    priority: { type: 'string', short: 'p' },\\n    due: { type: 'string', short: 'd' },\\n    project: { type: 'string', short: 'P' },\\n    parent: { type: 'string' },\\n    note: { type: 'string', short: 'n' },\\n    done: { type: 'boolean' },\\n    reopen: { type: 'boolean' },\\n  }),\\n\\n  delete: g({\\n    force: { type: 'boolean', short: 'f' },\\n    yes: { type: 'boolean', short: 'y' },\\n    recursive: { type: 'boolean' },\\n  }),\\n\\n  tags: g({ all: { type: 'boolean', short: 'a' }, done: { type: 'boolean' } }),\\n  projects: g({ all: { type: 'boolean', short: 'a' }, done: { type: 'boolean' } }),\\n\\n  completion: g({}),\\n  help: g({}),\\n  __complete: g({}),\\n};\\n\\n// ---------------------------------------------------------------------------\\n// Output plumbing\\n// ---------------------------------------------------------------------------\\n\\nfunction out(text) {\\n  process.stdout.write(text.endsWith('\\\\n') ? text : text + '\\\\n');\\n}\\n\\nfunction note(text) {\\n  process.stderr.write(text.endsWith('\\\\n') ? text : text + '\\\\n');\\n}\\n\\nfunction emitJson(value) {\\n  process.stdout.write(JSON.stringify(value, null, 2) + '\\\\n');\\n}\\n\\nfunction makeContext(flags) {\\n  const json = flags.json === true;\\n  const styles = render.makeStyles(\\n    render.colorEnabled({\\n      json,\\n      noColor: flags['no-color'] === true,\\n      forceColor: flags.color === true,\\n      stream: process.stdout,\\n      env: process.env,\\n    })\\n  );\\n  return {\\n    json,\\n    styles,\\n    now: new Date(),\\n    file: store.resolvePath(flags.file),\\n    terminalWidth: process.stdout.isTTY ? (process.stdout.columns || 0) : 0,\\n  };\\n}\\n\\nfunction readStdin() {\\n  const chunks = [];\\n  const buf = Buffer.alloc(64 * 1024);\\n  while (true) {\\n    let n;\\n    try {\\n      n = fs.readSync(0, buf, 0, buf.length, null);\\n    } catch (err) {\\n      if (err.code === 'EAGAIN') continue;             // non-blocking pipe, try again\\n      if (err.code === 'EOF' || err.code === 'EBADF') break;\\n      throw new AppError(`cannot read stdin: ${err.message}`, { code: 'io' });\\n    }\\n    if (n === 0) break;\\n    chunks.push(Buffer.from(buf.slice(0, n)));\\n  }\\n  return Buffer.concat(chunks).toString('utf8');\\n}\\n\\n/** Ask on the terminal. Returns true only for an explicit yes. */\\nfunction confirm(question) {\\n  process.stderr.write(question);\\n  const buf = Buffer.alloc(1);\\n  let answer = '';\\n  while (true) {\\n    let n;\\n    try {\\n      n = fs.readSync(0, buf, 0, 1, null);\\n    } catch (err) {\\n      if (err.code === 'EAGAIN') continue;\\n      process.stderr.write('\\\\n');\\n      return false;\\n    }\\n    if (n === 0) break;\\n    const ch = buf.toString('utf8');\\n    if (ch === '\\\\n') break;\\n    if (ch === '\\\\r') continue;\\n    answer += ch;\\n  }\\n  return /^y(es)?$/i.test(answer.trim());\\n}\\n\\n// ---------------------------------------------------------------------------\\n// Shared argument helpers\\n// ---------------------------------------------------------------------------\\n\\nfunction requireIds(positional, what) {\\n  if (positional.length === 0) {\\n    throw new UsageError(`${what} needs at least one task id`, { hint: `try \\\"todo help ${what}\\\"` });\\n  }\\n  return positional.map((p) => model.parseId(p));\\n}\\n\\nfunction parseLimit(raw) {\\n  if (raw === undefined) return null;\\n  if (!/^\\\\d+$/.test(String(raw).trim())) throw new UsageError(`--limit expects a whole number, got \\\"${raw}\\\"`);\\n  return Number(raw);\\n}\\n\\nfunction resolveParent(db, raw) {\\n  const s = String(raw).trim().toLowerCase();\\n  if (s === '' || s === 'none' || s === 'root' || s === '-' || s === '0') return null;\\n  const id = model.parseId(raw);\\n  model.mustFindTask(db, id);\\n  return id;\\n}\\n\\nfunction statusFrom(flags) {\\n  if (flags.all) return 'all';\\n  if (flags.done) return 'done';\\n  return 'pending';\\n}\\n\\nfunction buildQuery(flags, db) {\\n  const query = {\\n    status: statusFrom(flags),\\n    tags: model.normalizeTags(flags.tag),\\n    anyTags: model.normalizeTags(flags['any-tag']),\\n    search: flags.search ?? null,\\n  };\\n  if (flags.priority !== undefined) {\\n    const s = String(flags.priority).trim().toLowerCase();\\n    query.priority = (s === 'none' || s === '') ? 'none' : model.parsePriority(flags.priority);\\n  }\\n  if (flags.project !== undefined) {\\n    const s = String(flags.project).trim();\\n    query.project = s.toLowerCase() === 'none' ? 'none' : (model.normalizeProject(s) ?? 'none');\\n  }\\n  if (flags.parent !== undefined) {\\n    const s = String(flags.parent).trim().toLowerCase();\\n    query.parent = (s === 'none' || s === 'root') ? 'none' : model.parseId(flags.parent);\\n    if (typeof query.parent === 'number') model.mustFindTask(db, query.parent);\\n  }\\n  if (flags.overdue) query.due = 'overdue';\\n  if (flags.due !== undefined) query.due = flags.due;\\n  return query;\\n}\\n\\n// ---------------------------------------------------------------------------\\n// Commands\\n// ---------------------------------------------------------------------------\\n\\nfunction cmdAdd(argv) {\\n  const { positional, flags } = parse(argv, SPECS.add);\\n  if (flags.help) { out(help.helpFor('add')); return 0; }\\n\\n  const ctx = makeContext(flags);\\n  const db = store.load(ctx.file);\\n\\n  const useStdin = flags.stdin || positional.length === 0;\\n  let titles;\\n  if (useStdin) {\\n    if (flags.stdin && positional.length > 0) {\\n      throw new UsageError('--stdin cannot be combined with a title on the command line');\\n    }\\n    if (process.stdin.isTTY && !flags.stdin) {\\n      throw new UsageError('add needs a title', {\\n        hint: 'e.g. todo add \\\"buy milk\\\"   —   or pipe one title per line into \\\"todo add\\\"',\\n      });\\n    }\\n    titles = readStdin()\\n      .split(/\\\\r?\\\\n/)\\n      .map((l) => l.trim())\\n      .filter((l) => l !== '');\\n    if (titles.length === 0) throw new UsageError('nothing to add: stdin was empty');\\n  } else {\\n    titles = [positional.join(' ')];\\n  }\\n\\n  const base = {\\n    tags: model.normalizeTags(flags.tag),\\n    priority: flags.priority !== undefined ? model.parsePriority(flags.priority) : null,\\n    due: flags.due !== undefined ? dates.parseDue(flags.due, ctx.now) : null,\\n    project: flags.project !== undefined ? model.normalizeProject(flags.project) : null,\\n    note: flags.note !== undefined && flags.note !== '' ? flags.note : null,\\n    parent: flags.parent !== undefined ? resolveParent(db, flags.parent) : null,\\n  };\\n\\n  const created = [];\\n  for (const raw of titles) {\\n    const fields = { ...base, tags: [...base.tags] };\\n    let title = raw;\\n    if (flags.parse) {\\n      const parsed = model.parseInline(raw, ctx.now);\\n      title = parsed.title;\\n      for (const t of parsed.tags) if (!fields.tags.includes(t)) fields.tags.push(t);\\n      if (parsed.project) fields.project = parsed.project;\\n      if (parsed.priority) fields.priority = parsed.priority;\\n      if (parsed.due) fields.due = parsed.due;\\n    }\\n    fields.title = title;\\n    const task = model.createTask(db, fields);\\n    if (flags.done) {\\n      task.done = true;\\n      task.completed_at = model.nowStamp();\\n    }\\n    created.push(task);\\n  }\\n\\n  store.save(ctx.file, db);\\n\\n  if (ctx.json) {\\n    emitJson(created.length === 1 ? model.toJSON(created[0]) : created.map(model.toJSON));\\n  } else {\\n    // stdout carries the ids and nothing else, so `id=$(todo add \\\"x\\\")` works.\\n    out(created.map((t) => t.id).join('\\\\n'));\\n  }\\n  return 0;\\n}\\n\\nfunction cmdList(argv) {\\n  const { positional, flags } = parse(argv, SPECS.list);\\n  if (flags.help) { out(help.helpFor('list')); return 0; }\\n  if (positional.length) {\\n    throw new UsageError(`list takes no arguments (got \\\"${positional[0]}\\\")`, {\\n      hint: 'did you mean --search ' + JSON.stringify(positional.join(' ')) + '?',\\n    });\\n  }\\n\\n  const ctx = makeContext(flags);\\n  const db = store.load(ctx.file);\\n\\n  const query = buildQuery(flags, db);\\n  let matched = model.filterTasks(db, query, ctx.now);\\n\\n  const sortKey = flags.sort !== undefined ? String(flags.sort).trim().toLowerCase() : null;\\n  let cmp;\\n  if (sortKey) {\\n    cmp = model.comparator(sortKey, flags.reverse);\\n  } else {\\n    const base = model.defaultComparator();\\n    // Reversing the comparator rather than the rows keeps sub-tasks\\n    // attached to their parent.\\n    cmp = flags.reverse ? (a, b) => -base(a, b) : base;\\n  }\\n  const limit = parseLimit(flags.limit);\\n\\n  let rows;\\n  if (flags.flat || flags.ids || ctx.json) {\\n    let sorted = [...matched].sort(cmp);\\n    if (limit !== null) sorted = sorted.slice(0, limit);\\n    rows = sorted.map((t) => ({ task: t, depth: 0 }));\\n  } else {\\n    rows = model.buildTree(matched, cmp);\\n    if (limit !== null) rows = rows.slice(0, limit);\\n  }\\n\\n  if (ctx.json) { emitJson(rows.map((r) => model.toJSON(r.task))); return 0; }\\n  if (flags.ids) { if (rows.length) out(rows.map((r) => r.task.id).join('\\\\n')); return 0; }\\n\\n  if (rows.length === 0) {\\n    note(query.status === 'done' ? 'No completed tasks.' : 'No matching tasks.');\\n    return 0;\\n  }\\n\\n  out(render.renderTable(rows, {\\n    styles: ctx.styles,\\n    now: ctx.now,\\n    relativeDates: flags.relative === true,\\n    terminalWidth: ctx.terminalWidth,\\n  }));\\n  return 0;\\n}\\n\\nfunction cmdShow(argv) {\\n  const { positional, flags } = parse(argv, SPECS.show);\\n  if (flags.help) { out(help.helpFor('show')); return 0; }\\n  if (positional.length === 0) throw new UsageError('show needs a task id', { hint: 'e.g. todo show 3' });\\n  if (positional.length > 1) throw new UsageError('show takes exactly one task id');\\n\\n  const ctx = makeContext(flags);\\n  const db = store.load(ctx.file);\\n  const task = model.mustFindTask(db, model.parseId(positional[0]));\\n\\n  if (ctx.json) { emitJson(model.toJSON(task)); return 0; }\\n  out(render.renderDetail(task, db, {\\n    styles: ctx.styles,\\n    now: ctx.now,\\n    terminalWidth: ctx.terminalWidth,\\n  }));\\n  return 0;\\n}\\n\\nfunction setDone(task, done) {\\n  if (task.done === done) return false;\\n  task.done = done;\\n  task.completed_at = done ? model.nowStamp() : null;\\n  task.updated_at = model.nowStamp();\\n  return true;\\n}\\n\\nfunction cmdSetStatus(argv, done) {\\n  const name = done ? 'done' : 'reopen';\\n  const { positional, flags } = parse(argv, SPECS[name]);\\n  if (flags.help) { out(help.helpFor(name)); return 0; }\\n\\n  const ctx = makeContext(flags);\\n  const db = store.load(ctx.file);\\n  const ids = requireIds(positional, name);\\n\\n  const touched = [];\\n  const unchanged = [];\\n  const missing = [];\\n\\n  for (const id of ids) {\\n    const task = model.findTask(db, id);\\n    if (!task) { missing.push(id); continue; }\\n    const targets = [task];\\n    if (flags.recursive) {\\n      for (const childId of model.descendantIds(db, id)) targets.push(model.findTask(db, childId));\\n    }\\n    for (const t of targets) {\\n      if (setDone(t, done)) touched.push(t);\\n      else if (t === task) unchanged.push(t);\\n    }\\n  }\\n\\n  if (touched.length) store.save(ctx.file, db);\\n\\n  if (ctx.json) {\\n    emitJson([...touched, ...unchanged].map(model.toJSON));\\n  } else {\\n    for (const t of touched) {\\n      out(`${ctx.styles.green(done ? '[x]' : '[ ]')} ${ctx.styles.dim('#' + t.id)} ${t.title}`);\\n    }\\n    for (const t of unchanged) {\\n      note(`#${t.id} was already ${done ? 'done' : 'open'}`);\\n    }\\n  }\\n\\n  for (const id of missing) note(`todo: no task with id ${id}`);\\n  return missing.length ? 1 : 0;\\n}\\n\\nfunction cmdEdit(argv) {\\n  const { positional, flags, seen } = parse(argv, SPECS.edit);\\n  if (flags.help) { out(help.helpFor('edit')); return 0; }\\n  if (positional.length === 0) throw new UsageError('edit needs a task id', { hint: 'e.g. todo edit 3 --due friday' });\\n  if (positional.length > 1) {\\n    throw new UsageError('edit changes one task at a time', {\\n      hint: 'quote the new title: todo edit 3 --title \\\"buy oat milk\\\"',\\n    });\\n  }\\n  if (flags.done && flags.reopen) throw new UsageError('--done and --reopen contradict each other');\\n\\n  const changeFlags = ['title', 'tag', 'add-tag', 'remove-tag', 'priority', 'due', 'project', 'parent', 'note', 'done', 'reopen'];\\n  const changes = changeFlags.filter((f) => seen.has(f) || flags[f] === true);\\n  if (changes.length === 0) {\\n    throw new UsageError('edit needs something to change', { hint: 'try \\\"todo help edit\\\"' });\\n  }\\n\\n  const ctx = makeContext(flags);\\n  const db = store.load(ctx.file);\\n  const task = model.mustFindTask(db, model.parseId(positional[0]));\\n\\n  if (seen.has('title')) {\\n    const title = String(flags.title).trim();\\n    if (title === '') throw new UsageError('a task needs a title');\\n    task.title = title;\\n  }\\n  if (seen.has('tag')) task.tags = model.normalizeTags(flags.tag);\\n  if (seen.has('add-tag')) {\\n    for (const t of model.normalizeTags(flags['add-tag'])) if (!task.tags.includes(t)) task.tags.push(t);\\n  }\\n  if (seen.has('remove-tag')) {\\n    const drop = model.normalizeTags(flags['remove-tag']);\\n    task.tags = task.tags.filter((t) => !drop.includes(t));\\n  }\\n  if (seen.has('priority')) task.priority = model.parsePriority(flags.priority);\\n  if (seen.has('due')) task.due = dates.parseDue(flags.due, ctx.now);\\n  if (seen.has('project')) task.project = model.normalizeProject(flags.project);\\n  if (seen.has('note')) task.note = String(flags.note) === '' || String(flags.note).toLowerCase() === 'none' ? null : flags.note;\\n  if (seen.has('parent')) {\\n    const parent = resolveParent(db, flags.parent);\\n    if (model.wouldCycle(db, task.id, parent)) {\\n      throw new UsageError(`#${parent} is #${task.id} or one of its sub-tasks — that would make a loop`);\\n    }\\n    task.parent = parent;\\n  }\\n  if (flags.done) setDone(task, true);\\n  if (flags.reopen) setDone(task, false);\\n\\n  task.updated_at = model.nowStamp();\\n  store.save(ctx.file, db);\\n\\n  if (ctx.json) emitJson(model.toJSON(task));\\n  else out(`${ctx.styles.dim('updated')} ${ctx.styles.dim('#' + task.id)} ${task.title}`);\\n  return 0;\\n}\\n\\nfunction cmdDelete(argv) {\\n  const { positional, flags } = parse(argv, SPECS.delete);\\n  if (flags.help) { out(help.helpFor('delete')); return 0; }\\n\\n  const ctx = makeContext(flags);\\n  const db = store.load(ctx.file);\\n  const ids = requireIds(positional, 'delete');\\n\\n  const missing = [];\\n  const targets = [];\\n  const seenIds = new Set();\\n  for (const id of ids) {\\n    const task = model.findTask(db, id);\\n    if (!task) { missing.push(id); continue; }\\n    const group = [id, ...(flags.recursive ? model.descendantIds(db, id) : [])];\\n    for (const gid of group) {\\n      if (seenIds.has(gid)) continue;\\n      seenIds.add(gid);\\n      targets.push(model.findTask(db, gid));\\n    }\\n  }\\n\\n  if (targets.length === 0) {\\n    for (const id of missing) note(`todo: no task with id ${id}`);\\n    return missing.length ? 1 : 0;\\n  }\\n\\n  if (!flags.force && !flags.yes) {\\n    if (!process.stdin.isTTY) {\\n      throw new UsageError(\\n        `refusing to delete ${targets.length} task${targets.length === 1 ? '' : 's'} without a terminal to confirm on`,\\n        { hint: 'pass --force when running from a script' }\\n      );\\n    }\\n    const list = targets.map((t) => `  #${t.id}  ${t.title}`).join('\\\\n');\\n    note(`Delete ${targets.length} task${targets.length === 1 ? '' : 's'}:`);\\n    note(list);\\n    const orphans = targets\\n      .flatMap((t) => db.tasks.filter((c) => c.parent === t.id))\\n      .filter((c) => !seenIds.has(c.id));\\n    if (orphans.length) {\\n      note(`${orphans.length} sub-task${orphans.length === 1 ? '' : 's'} will move to the top level.`);\\n    }\\n    if (!confirm('Continue? [y/N] ')) {\\n      throw new AppError('cancelled', { code: 'cancelled' });\\n    }\\n  }\\n\\n  // Surviving children of a deleted task are lifted to the top level rather\\n  // than silently disappearing.\\n  for (const t of targets) {\\n    for (const child of db.tasks) {\\n      if (child.parent === t.id && !seenIds.has(child.id)) {\\n        child.parent = null;\\n        child.updated_at = model.nowStamp();\\n      }\\n    }\\n  }\\n  db.tasks = db.tasks.filter((t) => !seenIds.has(t.id));\\n  store.save(ctx.file, db);   // nextId is untouched, so ids are never reused\\n\\n  if (ctx.json) emitJson(targets.map(model.toJSON));\\n  else for (const t of targets) out(`${ctx.styles.red('deleted')} ${ctx.styles.dim('#' + t.id)} ${t.title}`);\\n\\n  for (const id of missing) note(`todo: no task with id ${id}`);\\n  return missing.length ? 1 : 0;\\n}\\n\\nfunction cmdFacet(argv, kind) {\\n  const { flags } = parse(argv, SPECS[kind]);\\n  if (flags.help) { out(help.helpFor(kind)); return 0; }\\n\\n  const ctx = makeContext(flags);\\n  const db = store.load(ctx.file);\\n  const tasks = model.filterTasks(db, { status: statusFrom(flags) }, ctx.now);\\n\\n  const counts = new Map();\\n  for (const t of tasks) {\\n    if (kind === 'tags') for (const tag of t.tags) counts.set(tag, (counts.get(tag) || 0) + 1);\\n    else if (t.project) counts.set(t.project, (counts.get(t.project) || 0) + 1);\\n  }\\n\\n  const rows = [...counts.entries()]\\n    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))\\n    .map(([name, count]) => ({ [kind === 'tags' ? 'tag' : 'project']: name, count }));\\n\\n  if (ctx.json) { emitJson(rows); return 0; }\\n  if (rows.length === 0) { note(`No ${kind} in use.`); return 0; }\\n\\n  const width = Math.max(...rows.map((r) => (r.tag || r.project).length));\\n  const paint = kind === 'tags' ? ctx.styles.cyan : ctx.styles.magenta;\\n  for (const r of rows) {\\n    const name = r.tag || r.project;\\n    out(`${paint(render.pad(name, width))}  ${ctx.styles.dim(String(r.count))}`);\\n  }\\n  return 0;\\n}\\n\\nfunction cmdCompletion(argv) {\\n  const { positional, flags } = parse(argv, SPECS.completion);\\n  if (flags.help) { out(help.helpFor('completion')); return 0; }\\n  const shell = String(positional[0] || '').toLowerCase();\\n  const files = { bash: 'todo.bash', zsh: 'todo.zsh', fish: 'todo.fish' };\\n  if (!files[shell]) {\\n    throw new UsageError(\\n      positional.length === 0 ? 'completion needs a shell name' : `no completion for \\\"${positional[0]}\\\"`,\\n      { hint: 'supported shells: bash, zsh, fish' }\\n    );\\n  }\\n  const file = path.join(__dirname, '..', 'completions', files[shell]);\\n  let script;\\n  try {\\n    script = fs.readFileSync(file, 'utf8');\\n  } catch (err) {\\n    throw new AppError(`completion script is missing: ${file}`, { code: 'io' });\\n  }\\n  process.stdout.write(script);\\n  return 0;\\n}\\n\\n/** Hidden helper the completion scripts call. Output is deliberately plain. */\\nfunction cmdComplete(argv) {\\n  const { positional, flags } = parse(argv, SPECS.__complete);\\n  const what = String(positional[0] || '').toLowerCase();\\n\\n  if (what === 'commands') {\\n    out(Object.keys(help.COMMANDS).join('\\\\n'));\\n    return 0;\\n  }\\n\\n  let db;\\n  try {\\n    db = store.load(store.resolvePath(flags.file));\\n  } catch {\\n    return 0;   // never let completion fail loudly\\n  }\\n\\n  const escape = (s) => s.replace(/[:\\\\t\\\\n]/g, ' ');\\n  const m = /^(all-|done-)?ids(?:-(zsh|fish))?$/.exec(what);\\n  if (m) {\\n    const scope = m[1] === 'all-' ? 'all' : m[1] === 'done-' ? 'done' : 'open';\\n    const tasks = db.tasks.filter((t) => scope === 'all' || (scope === 'done' ? t.done : !t.done));\\n    const lines = tasks.map((t) => {\\n      if (m[2] === 'zsh') return `${t.id}:${escape(t.title)}`;\\n      if (m[2] === 'fish') return `${t.id}\\\\t${escape(t.title)}`;\\n      return String(t.id);\\n    });\\n    if (lines.length) out(lines.join('\\\\n'));\\n    return 0;\\n  }\\n\\n  if (what === 'tags') {\\n    const tags = [...new Set(db.tasks.flatMap((t) => t.tags))].sort();\\n    if (tags.length) out(tags.join('\\\\n'));\\n    return 0;\\n  }\\n  if (what === 'projects') {\\n    const projects = [...new Set(db.tasks.map((t) => t.project).filter(Boolean))].sort();\\n    if (projects.length) out(projects.join('\\\\n'));\\n    return 0;\\n  }\\n  return 0;\\n}\\n\\nfunction cmdHelp(argv) {\\n  const { positional } = parse(argv, SPECS.help);\\n  if (positional.length === 0) { out(help.MAIN); return 0; }\\n  const topic = String(positional[0]).toLowerCase();\\n  const text = help.helpFor(topic);\\n  if (!text) throw new UsageError(`no help for \\\"${positional[0]}\\\"`, { hint: 'run \\\"todo help\\\" for the command list' });\\n  out(text);\\n  return 0;\\n}\\n\\n// ---------------------------------------------------------------------------\\n// Entry point\\n// ---------------------------------------------------------------------------\\n\\nconst HANDLERS = {\\n  add: cmdAdd,\\n  list: cmdList,\\n  show: cmdShow,\\n  done: (argv) => cmdSetStatus(argv, true),\\n  reopen: (argv) => cmdSetStatus(argv, false),\\n  edit: cmdEdit,\\n  delete: cmdDelete,\\n  tags: (argv) => cmdFacet(argv, 'tags'),\\n  projects: (argv) => cmdFacet(argv, 'projects'),\\n  completion: cmdCompletion,\\n  help: cmdHelp,\\n  __complete: cmdComplete,\\n};\\n\\nfunction editDistance(a, b) {\\n  const prev = Array.from({ length: b.length + 1 }, (_, i) => i);\\n  for (let i = 1; i <= a.length; i++) {\\n    let diag = prev[0];\\n    prev[0] = i;\\n    for (let j = 1; j <= b.length; j++) {\\n      const tmp = prev[j];\\n      prev[j] = Math.min(prev[j] + 1, prev[j - 1] + 1, diag + (a[i - 1] === b[j - 1] ? 0 : 1));\\n      diag = tmp;\\n    }\\n  }\\n  return prev[b.length];\\n}\\n\\nfunction didYouMean(word) {\\n  const w = word.toLowerCase();\\n  const names = [...Object.keys(HANDLERS), ...Object.keys(help.ALIASES)]\\n    .filter((n) => !n.startsWith('__') && n.length > 1);\\n  let best = null;\\n  let bestScore = Infinity;\\n  for (const n of names) {\\n    const score = n.startsWith(w) || w.startsWith(n) ? 0 : editDistance(w, n);\\n    if (score < bestScore) { best = n; bestScore = score; }\\n  }\\n  const threshold = Math.max(2, Math.floor(w.length / 2));\\n  return best && bestScore <= threshold\\n    ? `did you mean \\\"${best}\\\"?`\\n    : 'run \\\"todo help\\\" for the command list';\\n}\\n\\nfunction reportError(err, jsonMode) {\\n  const known = err instanceof UsageError || err instanceof AppError;\\n  const code = known ? err.exitCode : 1;\\n  if (jsonMode) {\\n    process.stderr.write(JSON.stringify({\\n      error: {\\n        code: known ? err.code : 'internal',\\n        message: err.message,\\n        ...(err.hint ? { hint: err.hint } : {}),\\n      },\\n    }) + '\\\\n');\\n  } else {\\n    process.stderr.write(`todo: ${known ? err.message : `internal error: ${err.message}`}\\\\n`);\\n    if (err.hint) process.stderr.write(`  ${err.hint}\\\\n`);\\n  }\\n  if (!known && process.env.TODO_DEBUG) process.stderr.write(err.stack + '\\\\n');\\n  return code;\\n}\\n\\nfunction main(argv) {\\n  // `todo list | head` closes the pipe early; that is not an error.\\n  for (const stream of [process.stdout, process.stderr]) {\\n    stream.on('error', (err) => { if (err.code === 'EPIPE') process.exit(0); });\\n  }\\n\\n  const jsonMode = argv.includes('--json');\\n  let code = 0;\\n  try {\\n    code = run(argv);\\n  } catch (err) {\\n    code = reportError(err, jsonMode);\\n  }\\n  process.exitCode = code;\\n  return code;\\n}\\n\\nfunction run(argv) {\\n  let commandIndex = -1;\\n  for (let i = 0; i < argv.length; i++) {\\n    if (argv[i] === '--') break;\\n    if (!argv[i].startsWith('-')) { commandIndex = i; break; }\\n    // Global value options consume the next argument.\\n    if (argv[i] === '--file') i++;\\n  }\\n\\n  if (commandIndex === -1) {\\n    const { flags } = parse(argv, SPECS.root);\\n    if (flags.version) { out(VERSION); return 0; }\\n    out(help.MAIN);\\n    return 0;\\n  }\\n\\n  const raw = argv[commandIndex];\\n  const name = help.ALIASES[raw] || raw;\\n  const handler = HANDLERS[name];\\n  if (!handler) {\\n    throw new UsageError(`unknown command \\\"${raw}\\\"`, { hint: didYouMean(raw) });\\n  }\\n\\n  const rest = [...argv.slice(0, commandIndex), ...argv.slice(commandIndex + 1)];\\n  return handler(rest);\\n}\\n\\nmodule.exports = { main, run, HANDLERS, VERSION };\\n\"},{\"path\":\"src/dates.js\",\"bytes\":4571,\"text\":\"'use strict';\\n\\nconst { UsageError } = require('./errors.js');\\n\\n// Due dates are plain local calendar days held as \\\"YYYY-MM-DD\\\" strings.\\n// Keeping them as strings means comparison is lexicographic and no timezone\\n// ever shifts a task by a day.\\n\\nconst ISO_RE = /^(\\\\d{4})-(\\\\d{2})-(\\\\d{2})$/;\\n\\nconst WEEKDAYS = {\\n  sun: 0, sunday: 0,\\n  mon: 1, monday: 1,\\n  tue: 2, tues: 2, tuesday: 2,\\n  wed: 3, weds: 3, wednesday: 3,\\n  thu: 4, thur: 4, thurs: 4, thursday: 4,\\n  fri: 5, friday: 5,\\n  sat: 6, saturday: 6,\\n};\\n\\nfunction toISO(date) {\\n  const y = String(date.getFullYear()).padStart(4, '0');\\n  const m = String(date.getMonth() + 1).padStart(2, '0');\\n  const d = String(date.getDate()).padStart(2, '0');\\n  return `${y}-${m}-${d}`;\\n}\\n\\nfunction today(now = new Date()) {\\n  return toISO(now);\\n}\\n\\nfunction fromISO(iso) {\\n  const m = ISO_RE.exec(iso);\\n  if (!m) return null;\\n  const [, y, mo, d] = m;\\n  const date = new Date(Number(y), Number(mo) - 1, Number(d));\\n  // Reject impossible dates such as 2026-02-31.\\n  if (date.getFullYear() !== Number(y) || date.getMonth() !== Number(mo) - 1 || date.getDate() !== Number(d)) {\\n    return null;\\n  }\\n  return date;\\n}\\n\\nfunction isValidISO(iso) {\\n  return fromISO(iso) !== null;\\n}\\n\\nfunction addDays(iso, days) {\\n  const date = fromISO(iso);\\n  if (!date) return null;\\n  date.setDate(date.getDate() + days);\\n  return toISO(date);\\n}\\n\\nfunction addMonths(iso, months) {\\n  const date = fromISO(iso);\\n  if (!date) return null;\\n  const day = date.getDate();\\n  date.setDate(1);\\n  date.setMonth(date.getMonth() + months);\\n  const lastDay = new Date(date.getFullYear(), date.getMonth() + 1, 0).getDate();\\n  date.setDate(Math.min(day, lastDay));\\n  return toISO(date);\\n}\\n\\nfunction diffDays(a, b) {\\n  const da = fromISO(a);\\n  const db = fromISO(b);\\n  if (!da || !db) return null;\\n  return Math.round((da.getTime() - db.getTime()) / 86400000);\\n}\\n\\n/**\\n * Parse a user-supplied due date.\\n * Returns an ISO string, or null when the input clears the date.\\n * Throws UsageError on anything unrecognised.\\n */\\nfunction parseDue(input, now = new Date()) {\\n  if (input === null || input === undefined) return null;\\n  const raw = String(input).trim();\\n  const s = raw.toLowerCase();\\n  const base = today(now);\\n\\n  if (s === '' || s === 'none' || s === 'never' || s === 'clear' || s === 'null' || s === '-') return null;\\n  if (s === 'today' || s === 'now') return base;\\n  if (s === 'tomorrow' || s === 'tom') return addDays(base, 1);\\n  if (s === 'yesterday') return addDays(base, -1);\\n  if (s === 'eow' || s === 'weekend') {\\n    // Upcoming Saturday (today if it is Saturday).\\n    const dow = fromISO(base).getDay();\\n    return addDays(base, (6 - dow + 7) % 7);\\n  }\\n  if (s === 'eom') {\\n    const d = fromISO(base);\\n    return toISO(new Date(d.getFullYear(), d.getMonth() + 1, 0));\\n  }\\n\\n  if (ISO_RE.test(s)) {\\n    if (!isValidISO(s)) throw new UsageError(`not a real date: \\\"${raw}\\\"`);\\n    return s;\\n  }\\n\\n  // Relative offsets: +3d, 3d, -1w, +2m, +1y\\n  const rel = /^([+-]?)(\\\\d+)\\\\s*([dwmy])$/.exec(s);\\n  if (rel) {\\n    const sign = rel[1] === '-' ? -1 : 1;\\n    const n = Number(rel[2]) * sign;\\n    switch (rel[3]) {\\n      case 'd': return addDays(base, n);\\n      case 'w': return addDays(base, n * 7);\\n      case 'm': return addMonths(base, n);\\n      case 'y': return addMonths(base, n * 12);\\n    }\\n  }\\n\\n  if (Object.prototype.hasOwnProperty.call(WEEKDAYS, s)) {\\n    const target = WEEKDAYS[s];\\n    const dow = fromISO(base).getDay();\\n    return addDays(base, (target - dow + 7) % 7);\\n  }\\n\\n  const nextWeekday = /^next\\\\s+(\\\\w+)$/.exec(s);\\n  if (nextWeekday && Object.prototype.hasOwnProperty.call(WEEKDAYS, nextWeekday[1])) {\\n    const target = WEEKDAYS[nextWeekday[1]];\\n    const dow = fromISO(base).getDay();\\n    const delta = (target - dow + 7) % 7;\\n    return addDays(base, delta === 0 ? 7 : delta);\\n  }\\n  if (s === 'next week') return addDays(base, 7);\\n  if (s === 'next month') return addMonths(base, 1);\\n\\n  throw new UsageError(\\n    `cannot understand date \\\"${raw}\\\"`,\\n    { hint: 'try: today, tomorrow, mon, +3d, 2w, next month, or 2026-08-31' }\\n  );\\n}\\n\\n/** Short human label for a due date relative to today. */\\nfunction relativeLabel(iso, now = new Date()) {\\n  const base = today(now);\\n  const d = diffDays(iso, base);\\n  if (d === null) return iso;\\n  if (d === 0) return 'today';\\n  if (d === 1) return 'tomorrow';\\n  if (d === -1) return 'yesterday';\\n  if (d < 0) return `${-d}d ago`;\\n  if (d <= 7) return `in ${d}d`;\\n  return iso;\\n}\\n\\nmodule.exports = {\\n  toISO, today, fromISO, isValidISO, addDays, addMonths, diffDays, parseDue, relativeLabel, WEEKDAYS,\\n};\\n\"},{\"path\":\"src/errors.js\",\"bytes\":921,\"text\":\"'use strict';\\n\\n/**\\n * Exit-code taxonomy:\\n *   0  success\\n *   1  runtime failure the user can act on (task not found, corrupt store,\\n *      cancelled confirmation, I/O error) — never a stack trace\\n *   2  usage error (unknown command/option, bad value, missing argument)\\n */\\n\\nclass UsageError extends Error {\\n  constructor(message, { code = 'usage', hint = null } = {}) {\\n    super(message);\\n    this.name = 'UsageError';\\n    this.exitCode = 2;\\n    this.code = code;\\n    this.hint = hint;\\n  }\\n}\\n\\nclass AppError extends Error {\\n  constructor(message, { code = 'error', hint = null } = {}) {\\n    super(message);\\n    this.name = 'AppError';\\n    this.exitCode = 1;\\n    this.code = code;\\n    this.hint = hint;\\n  }\\n}\\n\\nclass NotFoundError extends AppError {\\n  constructor(message) {\\n    super(message, { code: 'not_found' });\\n    this.name = 'NotFoundError';\\n  }\\n}\\n\\nmodule.exports = { UsageError, AppError, NotFoundError };\\n\"},{\"path\":\"src/help.js\",\"bytes\":8446,\"text\":\"'use strict';\\n\\nconst GLOBAL_OPTIONS = `GLOBAL OPTIONS\\n  --file <path>     Task file to use (default: $XDG_DATA_HOME/todo/todos.json)\\n  --json            Machine-readable JSON output, stable field names\\n  --no-color        Never colourise (also: NO_COLOR=1, or output not a terminal)\\n  --color           Colourise even when piped\\n  -h, --help        Show help for a command\\n  -V, --version     Print the version`;\\n\\nconst MAIN = `todo — manage a task list from the terminal\\n\\nUSAGE\\n  todo <command> [options]\\n\\nCOMMANDS\\n  add               Add a task (or many, from stdin)\\n  list, ls          List tasks, with filters\\n  show              Show one task in detail\\n  done              Mark tasks complete\\n  reopen            Mark tasks open again\\n  edit              Change a task's fields\\n  delete, rm        Delete tasks (confirms, or --force)\\n  tags              List tags in use\\n  projects          List projects in use\\n  completion        Print a shell completion script (bash, zsh, fish)\\n  help              Show help for a command\\n\\n${GLOBAL_OPTIONS}\\n\\nEXIT CODES\\n  0  success\\n  1  runtime failure — task not found, unreadable file, cancelled prompt\\n  2  usage error — unknown command or option, bad value\\n\\nEXAMPLES\\n  todo add \\\"buy milk\\\"                        # prints the new id\\n  todo add \\\"ship release\\\" --due friday -p high --tag work\\n  todo list --tag work --due today\\n  todo list --done\\n  todo done 3\\n  todo edit 3 --title \\\"buy oat milk\\\" --due tomorrow\\n  todo delete 3 --force\\n  todo list --json | jq '.[] | select(.priority == \\\"high\\\") | .title'\\n  git log --format=%s -5 | todo add --tag review\\n\\n  todo help add                              # per-command help, with examples`;\\n\\nconst COMMANDS = {\\n  add: `todo add — add a task\\n\\nUSAGE\\n  todo add <title...> [options]\\n  todo add [options] < lines.txt        # one task per line, from stdin\\n\\n  Prints the id of each new task, so a script can capture it:\\n    id=$(todo add \\\"buy milk\\\")\\n\\nOPTIONS\\n  -t, --tag <tag>        Tag the task; repeatable, or comma-separated\\n  -p, --priority <p>     high | medium | low  (h/m/l also work)\\n  -d, --due <when>       today, tomorrow, mon, +3d, 2w, eom, 2026-08-31, none\\n  -P, --project <name>   Group the task under a project\\n      --parent <id>      Make this a sub-task of <id>\\n  -n, --note <text>      Free-text note\\n      --done             Add the task already completed\\n      --parse            Read +tag @project !priority due:when out of the title\\n      --stdin            Force reading titles from stdin\\n\\nEXAMPLES\\n  todo add \\\"buy milk\\\"\\n  todo add buy milk --tag home --due tomorrow\\n  todo add \\\"write tests\\\" --parent 4 --priority high\\n  todo add --parse \\\"fix login +bug @web !high due:friday\\\"\\n  printf 'first\\\\\\\\nsecond\\\\\\\\n' | todo add --project inbox\\n  todo add \\\"deploy\\\" --json | jq -r .id`,\\n\\n  list: `todo list — list tasks\\n\\nUSAGE\\n  todo list [filters] [options]\\n\\n  Open tasks only, unless you ask otherwise. Sub-tasks are printed\\n  underneath their parent when both are in the result.\\n\\nFILTERS\\n      --done             Only completed tasks\\n  -a, --all              Both open and completed\\n  -t, --tag <tag>        Must have this tag; repeatable (AND)\\n      --any-tag <tag>    Must have at least one of these (OR)\\n  -p, --priority <p>     high | medium | low | none\\n  -d, --due <when>       today, tomorrow, overdue, week, month, none, any,\\n                         2026-08-31, before:friday, after:2026-09-01\\n      --overdue          Shorthand for --due overdue\\n  -P, --project <name>   Only this project (\\\"none\\\" for tasks with no project)\\n      --parent <id>      Only sub-tasks of <id> (\\\"none\\\" for top-level only)\\n  -s, --search <text>    Substring match on title, note, project and tags\\n\\nOPTIONS\\n      --sort <key>       id | due | priority | created | updated | title |\\n                         project | status   (default: smart)\\n  -r, --reverse          Reverse the sort\\n  -n, --limit <n>        Show at most n tasks\\n      --flat             Do not indent sub-tasks under their parent\\n      --relative         Show due dates as \\\"today\\\"/\\\"in 3d\\\"\\n      --ids              Print only ids, one per line\\n      --json             JSON array of task objects\\n\\nEXAMPLES\\n  todo list\\n  todo list --done\\n  todo list --tag work --due today\\n  todo list --overdue --sort due\\n  todo list --all --project website\\n  todo list --ids --tag work | xargs -n1 todo done\\n  todo list --json | jq -r '.[] | \\\"\\\\\\\\(.id)\\\\\\\\t\\\\\\\\(.title)\\\"'`,\\n\\n  show: `todo show — show one task in detail\\n\\nUSAGE\\n  todo show <id> [--json]\\n\\n  Prints every field, plus any sub-tasks.\\n\\nEXAMPLES\\n  todo show 3\\n  todo show 3 --json | jq .tags`,\\n\\n  done: `todo done — mark tasks complete\\n\\nUSAGE\\n  todo done <id...> [options]\\n\\nOPTIONS\\n      --recursive        Also complete every sub-task\\n      --json             JSON array of the updated tasks\\n\\n  Completing a task that is already done is not an error.\\n  An unknown id reports the failure and exits 1; other ids still get done.\\n\\nEXAMPLES\\n  todo done 3\\n  todo done 3 4 5\\n  todo done 2 --recursive`,\\n\\n  reopen: `todo reopen — mark tasks open again\\n\\nUSAGE\\n  todo reopen <id...> [options]\\n\\nOPTIONS\\n      --recursive        Also reopen every sub-task\\n      --json             JSON array of the updated tasks\\n\\nEXAMPLES\\n  todo reopen 3\\n  todo reopen 3 4 --recursive`,\\n\\n  edit: `todo edit — change a task\\n\\nUSAGE\\n  todo edit <id> [options]\\n\\n  At least one change is required.\\n\\nOPTIONS\\n  -m, --title <text>       Replace the title\\n  -t, --tag <tag>          Replace all tags with these\\n      --add-tag <tag>      Add a tag; repeatable\\n      --remove-tag <tag>   Remove a tag; repeatable\\n  -p, --priority <p>       high | medium | low | none\\n  -d, --due <when>         today, +3d, 2026-08-31, none\\n  -P, --project <name>     Project name, or \\\"none\\\"\\n      --parent <id>        Re-parent the task (\\\"none\\\" to make it top-level)\\n  -n, --note <text>        Replace the note (\\\"\\\" or \\\"none\\\" to clear)\\n      --done / --reopen    Change completion state\\n      --json               The updated task as JSON\\n\\nEXAMPLES\\n  todo edit 3 --title \\\"buy oat milk\\\"\\n  todo edit 3 --due friday --priority high\\n  todo edit 3 --add-tag urgent --remove-tag someday\\n  todo edit 3 --project none --parent 7`,\\n\\n  delete: `todo delete — delete tasks\\n\\nUSAGE\\n  todo delete <id...> [options]\\n\\n  Asks for confirmation on a terminal. Without a terminal it refuses\\n  unless --force is given, so a script never deletes by surprise.\\n\\nOPTIONS\\n  -f, --force            Do not ask (-y, --yes is the same)\\n      --recursive        Also delete every sub-task\\n      --json             JSON array of the deleted tasks\\n\\n  Deleting a task with sub-tasks lifts them to top level unless\\n  --recursive is given. Ids are never reused after a delete.\\n\\nEXAMPLES\\n  todo delete 3\\n  todo delete 3 4 --force\\n  todo delete 2 --recursive --force`,\\n\\n  tags: `todo tags — list tags in use\\n\\nUSAGE\\n  todo tags [--all] [--done] [--json]\\n\\n  Shows each tag with a count of matching tasks (open tasks by default).\\n\\nEXAMPLES\\n  todo tags\\n  todo tags --all\\n  todo tags --json | jq -r '.[].tag'`,\\n\\n  projects: `todo projects — list projects in use\\n\\nUSAGE\\n  todo projects [--all] [--done] [--json]\\n\\nEXAMPLES\\n  todo projects\\n  todo projects --all`,\\n\\n  completion: `todo completion — print a shell completion script\\n\\nUSAGE\\n  todo completion <bash|zsh|fish>\\n\\nINSTALL\\n  bash    todo completion bash > /etc/bash_completion.d/todo\\n          # or: echo 'source <(todo completion bash)' >> ~/.bashrc\\n  zsh     todo completion zsh > \\\"\\\\${fpath[1]}/_todo\\\"\\n          # then restart the shell (compinit must run after)\\n  fish    todo completion fish > ~/.config/fish/completions/todo.fish\\n\\n  Completion suggests commands, options, live task ids, tags and projects.\\n\\nEXAMPLES\\n  todo completion bash\\n  source <(todo completion bash)`,\\n\\n  help: `todo help — show help\\n\\nUSAGE\\n  todo help [command]\\n\\nEXAMPLES\\n  todo help\\n  todo help add`,\\n};\\n\\nconst ALIASES = {\\n  ls: 'list', l: 'list', a: 'add', rm: 'delete', remove: 'delete', del: 'delete',\\n  complete: 'done', do: 'done', finish: 'done',\\n  undone: 'reopen', undo: 'reopen', open: 'reopen',\\n  update: 'edit', modify: 'edit', view: 'show', info: 'show', cat: 'show',\\n  tag: 'tags', project: 'projects', completions: 'completion',\\n};\\n\\nfunction helpFor(command) {\\n  const name = ALIASES[command] || command;\\n  const body = COMMANDS[name];\\n  if (!body) return null;\\n  return `${body}\\\\n\\\\n${GLOBAL_OPTIONS}`;\\n}\\n\\nmodule.exports = { MAIN, COMMANDS, ALIASES, GLOBAL_OPTIONS, helpFor };\\n\"},{\"path\":\"src/model.js\",\"bytes\":10871,\"text\":\"'use strict';\\n\\nconst { UsageError, NotFoundError } = require('./errors.js');\\nconst dates = require('./dates.js');\\n\\nconst PRIORITIES = ['high', 'medium', 'low'];\\nconst PRIORITY_RANK = { high: 0, medium: 1, low: 2 };\\n\\nconst PRIORITY_ALIASES = {\\n  h: 'high', hi: 'high', high: 'high', '1': 'high', urgent: 'high',\\n  m: 'medium', med: 'medium', mid: 'medium', medium: 'medium', normal: 'medium', '2': 'medium',\\n  l: 'low', lo: 'low', low: 'low', '3': 'low',\\n};\\n\\nfunction parsePriority(input) {\\n  if (input === null || input === undefined) return null;\\n  const s = String(input).trim().toLowerCase();\\n  if (s === '' || s === 'none' || s === 'clear' || s === '-') return null;\\n  const p = PRIORITY_ALIASES[s];\\n  if (!p) {\\n    throw new UsageError(`unknown priority \\\"${input}\\\"`, { hint: 'use high, medium or low (h/m/l also work)' });\\n  }\\n  return p;\\n}\\n\\nfunction normalizeTag(input) {\\n  const t = String(input).trim().replace(/^[#+]/, '').toLowerCase();\\n  if (t === '') return null;\\n  if (/\\\\s/.test(t)) throw new UsageError(`tags cannot contain spaces: \\\"${input}\\\"`);\\n  return t;\\n}\\n\\nfunction normalizeTags(list) {\\n  const out = [];\\n  for (const item of list || []) {\\n    const t = normalizeTag(item);\\n    if (t && !out.includes(t)) out.push(t);\\n  }\\n  return out;\\n}\\n\\nfunction normalizeProject(input) {\\n  if (input === null || input === undefined) return null;\\n  const p = String(input).trim().replace(/^@/, '');\\n  if (p === '' || p.toLowerCase() === 'none' || p === '-') return null;\\n  return p;\\n}\\n\\nfunction nowStamp() {\\n  return new Date().toISOString();\\n}\\n\\nfunction parseId(input) {\\n  const s = String(input).trim().replace(/^#/, '');\\n  if (!/^\\\\d+$/.test(s)) throw new UsageError(`not a task id: \\\"${input}\\\"`);\\n  const n = Number(s);\\n  if (n < 1) throw new UsageError(`not a task id: \\\"${input}\\\"`);\\n  return n;\\n}\\n\\nfunction findTask(db, id) {\\n  return db.tasks.find((t) => t.id === id) || null;\\n}\\n\\nfunction mustFindTask(db, id) {\\n  const task = findTask(db, id);\\n  if (!task) throw new NotFoundError(`no task with id ${id}`);\\n  return task;\\n}\\n\\n/**\\n * Ids come from a monotonically increasing counter held in the file, so a\\n * deleted id is never handed out again.\\n */\\nfunction createTask(db, fields) {\\n  const title = String(fields.title || '').trim();\\n  if (title === '') throw new UsageError('a task needs a title');\\n\\n  const task = {\\n    id: db.nextId,\\n    title,\\n    done: false,\\n    priority: fields.priority ?? null,\\n    due: fields.due ?? null,\\n    tags: fields.tags ? [...fields.tags] : [],\\n    project: fields.project ?? null,\\n    parent: fields.parent ?? null,\\n    note: fields.note ?? null,\\n    created_at: nowStamp(),\\n    updated_at: nowStamp(),\\n    completed_at: null,\\n  };\\n  db.nextId += 1;\\n  db.tasks.push(task);\\n  return task;\\n}\\n\\n/** Ids of a task plus everything nested underneath it. */\\nfunction descendantIds(db, id) {\\n  const out = [];\\n  const walk = (parentId) => {\\n    for (const t of db.tasks) {\\n      if (t.parent === parentId) { out.push(t.id); walk(t.id); }\\n    }\\n  };\\n  walk(id);\\n  return out;\\n}\\n\\nfunction wouldCycle(db, id, newParent) {\\n  if (newParent === null) return false;\\n  if (newParent === id) return true;\\n  return descendantIds(db, id).includes(newParent);\\n}\\n\\n// ---------------------------------------------------------------------------\\n// Filtering\\n// ---------------------------------------------------------------------------\\n\\nfunction makeDueFilter(spec, now = new Date()) {\\n  const raw = String(spec).trim().toLowerCase();\\n  const base = dates.today(now);\\n\\n  if (raw === 'any' || raw === 'set') return (t) => t.due !== null;\\n  if (raw === 'none' || raw === 'unset') return (t) => t.due === null;\\n  if (raw === 'overdue' || raw === 'late') return (t) => t.due !== null && t.due < base;\\n  if (raw === 'week' || raw === 'this week' || raw === '7d') {\\n    const end = dates.addDays(base, 7);\\n    return (t) => t.due !== null && t.due <= end;\\n  }\\n  if (raw === 'month' || raw === '30d') {\\n    const end = dates.addDays(base, 30);\\n    return (t) => t.due !== null && t.due <= end;\\n  }\\n\\n  const ranged = /^(before|until|after|since|on)[:=](.+)$/.exec(raw);\\n  if (ranged) {\\n    const at = dates.parseDue(ranged[2], now);\\n    if (at === null) throw new UsageError(`--due ${ranged[1]} needs a real date`);\\n    switch (ranged[1]) {\\n      case 'before': return (t) => t.due !== null && t.due < at;\\n      case 'until': return (t) => t.due !== null && t.due <= at;\\n      case 'after': return (t) => t.due !== null && t.due > at;\\n      case 'since': return (t) => t.due !== null && t.due >= at;\\n      case 'on': return (t) => t.due === at;\\n    }\\n  }\\n\\n  const at = dates.parseDue(raw, now);\\n  if (at === null) return (t) => t.due === null;\\n  return (t) => t.due === at;\\n}\\n\\n/**\\n * @param {object} db\\n * @param {object} query\\n * @param {'pending'|'done'|'all'} query.status\\n * @param {string[]} query.tags     all must be present\\n * @param {string[]} query.anyTags  at least one must be present\\n * @param {string|null} query.project\\n * @param {string|null} query.priority\\n * @param {string|null} query.due\\n * @param {number|null} query.parent\\n * @param {string|null} query.search\\n */\\nfunction filterTasks(db, query = {}, now = new Date()) {\\n  const status = query.status || 'pending';\\n  const tags = query.tags || [];\\n  const anyTags = query.anyTags || [];\\n  const dueFilter = query.due ? makeDueFilter(query.due, now) : null;\\n  const search = query.search ? String(query.search).toLowerCase() : null;\\n\\n  return db.tasks.filter((t) => {\\n    if (status === 'pending' && t.done) return false;\\n    if (status === 'done' && !t.done) return false;\\n    if (tags.length && !tags.every((tag) => t.tags.includes(tag))) return false;\\n    if (anyTags.length && !anyTags.some((tag) => t.tags.includes(tag))) return false;\\n    if (query.project !== null && query.project !== undefined) {\\n      const want = String(query.project).toLowerCase();\\n      const have = t.project === null ? '' : t.project.toLowerCase();\\n      if (want === 'none' ? have !== '' : have !== want) return false;\\n    }\\n    if (query.priority) {\\n      if (query.priority === 'none' ? t.priority !== null : t.priority !== query.priority) return false;\\n    }\\n    if (query.parent !== null && query.parent !== undefined) {\\n      if (query.parent === 'none' ? t.parent !== null : t.parent !== query.parent) return false;\\n    }\\n    if (dueFilter && !dueFilter(t)) return false;\\n    if (search) {\\n      const haystack = [t.title, t.note || '', t.project || '', ...t.tags].join(' ').toLowerCase();\\n      if (!haystack.includes(search)) return false;\\n    }\\n    return true;\\n  });\\n}\\n\\nconst SORT_KEYS = ['id', 'due', 'priority', 'created', 'updated', 'title', 'project', 'status'];\\n\\nfunction comparator(key, reverse) {\\n  const dir = reverse ? -1 : 1;\\n  const byId = (a, b) => (a.id - b.id) * dir;\\n  const nullsLast = (a, b, pick) => {\\n    const va = pick(a); const vb = pick(b);\\n    if (va === null && vb === null) return 0;\\n    if (va === null) return 1;   // missing values always sink, in both directions\\n    if (vb === null) return -1;\\n    if (va < vb) return -1 * dir;\\n    if (va > vb) return 1 * dir;\\n    return 0;\\n  };\\n\\n  switch (key) {\\n    case 'due': return (a, b) => nullsLast(a, b, (t) => t.due) || byId(a, b);\\n    case 'priority':\\n      return (a, b) => nullsLast(a, b, (t) => (t.priority ? PRIORITY_RANK[t.priority] : null)) || byId(a, b);\\n    case 'title':\\n      return (a, b) => nullsLast(a, b, (t) => t.title.toLowerCase()) || byId(a, b);\\n    case 'project': return (a, b) => nullsLast(a, b, (t) => (t.project || '').toLowerCase()) || byId(a, b);\\n    case 'created': return (a, b) => nullsLast(a, b, (t) => t.created_at) || byId(a, b);\\n    case 'updated': return (a, b) => nullsLast(a, b, (t) => t.updated_at) || byId(a, b);\\n    case 'status': return (a, b) => ((a.done ? 1 : 0) - (b.done ? 1 : 0)) * dir || byId(a, b);\\n    case 'id': return byId;\\n    default:\\n      throw new UsageError(`unknown sort key \\\"${key}\\\"`, { hint: `try one of: ${SORT_KEYS.join(', ')}` });\\n  }\\n}\\n\\n/** Default order: open first, then by priority, then by soonest due, then id. */\\nfunction defaultComparator() {\\n  return (a, b) => {\\n    if (a.done !== b.done) return a.done ? 1 : -1;\\n    const pa = a.priority ? PRIORITY_RANK[a.priority] : 3;\\n    const pb = b.priority ? PRIORITY_RANK[b.priority] : 3;\\n    if (pa !== pb) return pa - pb;\\n    if (a.due !== b.due) {\\n      if (a.due === null) return 1;\\n      if (b.due === null) return -1;\\n      return a.due < b.due ? -1 : 1;\\n    }\\n    return a.id - b.id;\\n  };\\n}\\n\\nfunction sortTasks(tasks, key, reverse) {\\n  const cmp = key ? comparator(key, reverse) : defaultComparator();\\n  return [...tasks].sort(cmp);\\n}\\n\\n/**\\n * Arrange a flat result set into parent/child order. A task whose parent is\\n * not in the set becomes a root, so filters never hide a matching task.\\n */\\nfunction buildTree(tasks, cmp) {\\n  const present = new Map(tasks.map((t) => [t.id, t]));\\n  const children = new Map();\\n  const roots = [];\\n\\n  for (const t of tasks) {\\n    if (t.parent !== null && present.has(t.parent)) {\\n      if (!children.has(t.parent)) children.set(t.parent, []);\\n      children.get(t.parent).push(t);\\n    } else {\\n      roots.push(t);\\n    }\\n  }\\n\\n  const out = [];\\n  const walk = (list, depth) => {\\n    for (const t of [...list].sort(cmp)) {\\n      out.push({ task: t, depth });\\n      const kids = children.get(t.id);\\n      if (kids) walk(kids, depth + 1);\\n    }\\n  };\\n  walk(roots, 0);\\n  return out;\\n}\\n\\n/**\\n * Pull inline `+tag`, `@project`, `!priority` and `due:…` tokens out of a\\n * title. Only used when --parse is given, so a plain title is never mangled.\\n */\\nfunction parseInline(text, now = new Date()) {\\n  const tags = [];\\n  let project = null;\\n  let priority = null;\\n  let due = null;\\n\\n  const words = text.split(/\\\\s+/);\\n  const kept = [];\\n  for (const w of words) {\\n    if (/^\\\\+[^\\\\s]+$/.test(w)) { const t = normalizeTag(w); if (t) tags.push(t); continue; }\\n    if (/^@[^\\\\s]+$/.test(w)) { project = normalizeProject(w); continue; }\\n    if (/^![^\\\\s]+$/.test(w)) { priority = parsePriority(w.slice(1)); continue; }\\n    const d = /^due:(.+)$/i.exec(w);\\n    if (d) { due = dates.parseDue(d[1], now); continue; }\\n    kept.push(w);\\n  }\\n\\n  return { title: kept.join(' ').trim(), tags, project, priority, due };\\n}\\n\\nfunction toJSON(task) {\\n  return {\\n    id: task.id,\\n    title: task.title,\\n    done: task.done,\\n    priority: task.priority,\\n    due: task.due,\\n    tags: task.tags,\\n    project: task.project,\\n    parent: task.parent,\\n    note: task.note,\\n    created_at: task.created_at,\\n    updated_at: task.updated_at,\\n    completed_at: task.completed_at,\\n  };\\n}\\n\\nmodule.exports = {\\n  PRIORITIES, PRIORITY_RANK, SORT_KEYS,\\n  parsePriority, normalizeTag, normalizeTags, normalizeProject, parseId,\\n  findTask, mustFindTask, createTask, descendantIds, wouldCycle,\\n  filterTasks, sortTasks, comparator, defaultComparator, buildTree,\\n  parseInline, toJSON, nowStamp, makeDueFilter,\\n};\\n\"},{\"path\":\"src/render.js\",\"bytes\":7892,\"text\":\"'use strict';\\n\\nconst dates = require('./dates.js');\\nconst ESC = String.fromCharCode(27);\\n\\nconst CODES = {\\n  reset: 0, bold: 1, dim: 2, underline: 4, strike: 9,\\n  red: 31, green: 32, yellow: 33, blue: 34, magenta: 35, cyan: 36, white: 37, gray: 90,\\n};\\n\\n/**\\n * Colour is on only when writing to a terminal. NO_COLOR (non-empty) always\\n * wins; --color / CLICOLOR_FORCE force it back on for things like `less -R`.\\n */\\nfunction colorEnabled({ json = false, noColor = false, forceColor = false, stream = process.stdout, env = process.env } = {}) {\\n  if (json) return false;\\n  if (noColor) return false;\\n  if (typeof env.NO_COLOR === 'string' && env.NO_COLOR !== '') return false;\\n  if (forceColor) return true;\\n  if (typeof env.CLICOLOR_FORCE === 'string' && env.CLICOLOR_FORCE !== '' && env.CLICOLOR_FORCE !== '0') return true;\\n  if (env.TERM === 'dumb') return false;\\n  return stream.isTTY === true;\\n}\\n\\nfunction makeStyles(enabled) {\\n  const styles = {};\\n  for (const [name, code] of Object.entries(CODES)) {\\n    styles[name] = enabled ? (s) => `${ESC}[${code}m${s}${ESC}[0m` : (s) => String(s);\\n  }\\n  styles.enabled = enabled;\\n  styles.plain = (s) => String(s);\\n  return styles;\\n}\\n\\nfunction stripAnsi(s) {\\n  // eslint-disable-next-line no-control-regex\\n  return String(s).replace(new RegExp(ESC + '\\\\\\\\[[0-9;]*m', 'g'), '');\\n}\\n\\nfunction width(s) {\\n  return stripAnsi(s).length;\\n}\\n\\nfunction pad(s, w, align = 'left') {\\n  const gap = Math.max(0, w - width(s));\\n  return align === 'right' ? ' '.repeat(gap) + s : s + ' '.repeat(gap);\\n}\\n\\nfunction truncate(s, max) {\\n  if (max <= 0) return '';\\n  if (s.length <= max) return s;\\n  if (max === 1) return '.';\\n  return s.slice(0, max - 1) + '…';\\n}\\n\\nfunction statusGlyph(task) {\\n  return task.done ? '[x]' : '[ ]';\\n}\\n\\nfunction priorityLabel(p) {\\n  if (!p) return '';\\n  return { high: 'high', medium: 'med', low: 'low' }[p] || p;\\n}\\n\\nfunction paintPriority(p, styles) {\\n  const label = priorityLabel(p);\\n  if (!label) return '';\\n  if (p === 'high') return styles.red(styles.bold(label));\\n  if (p === 'medium') return styles.yellow(label);\\n  return styles.dim(label);\\n}\\n\\nfunction paintDue(task, styles, now, relative) {\\n  if (!task.due) return '';\\n  const today = dates.today(now);\\n  const text = relative ? dates.relativeLabel(task.due, now) : task.due;\\n  if (task.done) return styles.dim(text);\\n  if (task.due < today) return styles.red(text);\\n  if (task.due === today) return styles.yellow(text);\\n  return text;\\n}\\n\\n/**\\n * Render a list of {task, depth} rows as an aligned table.\\n * Columns that are empty for every row are dropped so short lists stay tidy.\\n */\\nfunction renderTable(rows, opts = {}) {\\n  const styles = opts.styles || makeStyles(false);\\n  const now = opts.now || new Date();\\n  const relative = opts.relativeDates === true;\\n  const tasks = rows.map((r) => r.task);\\n\\n  const showPriority = tasks.some((t) => t.priority);\\n  const showDue = tasks.some((t) => t.due);\\n  const showProject = tasks.some((t) => t.project);\\n  const showTags = tasks.some((t) => t.tags.length);\\n\\n  const columns = [\\n    { key: 'id', header: 'ID', align: 'right' },\\n    { key: 'status', header: '', align: 'left' },\\n  ];\\n  if (showPriority) columns.push({ key: 'priority', header: 'PRI', align: 'left' });\\n  if (showDue) columns.push({ key: 'due', header: 'DUE', align: 'left' });\\n  if (showProject) columns.push({ key: 'project', header: 'PROJECT', align: 'left' });\\n  if (showTags) columns.push({ key: 'tags', header: 'TAGS', align: 'left' });\\n  columns.push({ key: 'title', header: 'TITLE', align: 'left' });\\n\\n  const cells = rows.map(({ task, depth }) => {\\n    const indent = '  '.repeat(depth);\\n    const bullet = depth > 0 ? '- ' : '';\\n    return {\\n      id: { text: String(task.id), styled: styles.dim(String(task.id)) },\\n      status: {\\n        text: statusGlyph(task),\\n        styled: task.done ? styles.green(statusGlyph(task)) : statusGlyph(task),\\n      },\\n      priority: { text: priorityLabel(task.priority), styled: paintPriority(task.priority, styles) },\\n      due: {\\n        text: task.due ? (relative ? dates.relativeLabel(task.due, now) : task.due) : '',\\n        styled: paintDue(task, styles, now, relative),\\n      },\\n      project: {\\n        text: task.project || '',\\n        styled: task.project ? styles.magenta(task.project) : '',\\n      },\\n      tags: {\\n        text: task.tags.join(','),\\n        styled: task.tags.length ? styles.cyan(task.tags.join(',')) : '',\\n      },\\n      title: { prefix: indent + bullet, text: task.title, task },\\n    };\\n  });\\n\\n  const widths = {};\\n  for (const col of columns) {\\n    let w = col.header.length;\\n    for (const row of cells) {\\n      const cell = row[col.key];\\n      const len = col.key === 'title' ? cell.prefix.length + cell.text.length : cell.text.length;\\n      if (len > w) w = len;\\n    }\\n    widths[col.key] = w;\\n  }\\n\\n  // Keep the last column inside the terminal when we have one.\\n  const term = opts.terminalWidth || 0;\\n  if (term > 20) {\\n    const fixed = columns\\n      .filter((c) => c.key !== 'title')\\n      .reduce((sum, c) => sum + widths[c.key] + 2, 0);\\n    const room = term - fixed - 1;\\n    if (room > 10 && widths.title > room) widths.title = room;\\n  }\\n\\n  const out = [];\\n  const header = columns\\n    .map((c) => pad(c.header, widths[c.key], c.align))\\n    .join('  ')\\n    .replace(/\\\\s+$/, '');\\n  out.push(styles.dim(styles.bold(header)));\\n\\n  for (const row of cells) {\\n    const parts = columns.map((col) => {\\n      if (col.key === 'title') {\\n        const room = Math.max(0, widths.title - row.title.prefix.length);\\n        const text = truncate(row.title.text, room);\\n        const painted = row.title.task.done ? styles.dim(text) : text;\\n        return pad(row.title.prefix + painted, widths.title, col.align);\\n      }\\n      const cell = row[col.key];\\n      return pad(cell.styled || cell.text, widths[col.key], col.align);\\n    });\\n    out.push(parts.join('  ').replace(/\\\\s+$/, ''));\\n  }\\n\\n  return out.join('\\\\n');\\n}\\n\\nfunction renderDetail(task, db, opts = {}) {\\n  const styles = opts.styles || makeStyles(false);\\n  const now = opts.now || new Date();\\n  const lines = [];\\n\\n  const heading = `${styles.dim('#' + task.id)}  ${task.done ? styles.dim(styles.strike(task.title)) : styles.bold(task.title)}`;\\n  lines.push(heading);\\n  lines.push('');\\n  const field = (label, value) => lines.push(`  ${styles.dim(pad(label + ':', 11))}${value}`);\\n\\n  field('status', task.done ? styles.green('done') : 'open');\\n  if (task.priority) field('priority', paintPriority(task.priority, styles));\\n  if (task.due) field('due', `${paintDue(task, styles, now, false)} (${dates.relativeLabel(task.due, now)})`);\\n  if (task.project) field('project', styles.magenta(task.project));\\n  if (task.tags.length) field('tags', styles.cyan(task.tags.join(', ')));\\n  if (task.parent !== null) {\\n    const parent = db ? db.tasks.find((t) => t.id === task.parent) : null;\\n    field('parent', `#${task.parent}${parent ? ` ${parent.title}` : ''}`);\\n  }\\n  if (db) {\\n    const kids = db.tasks.filter((t) => t.parent === task.id);\\n    if (kids.length) {\\n      const openCount = kids.filter((k) => !k.done).length;\\n      field('subtasks', `${kids.length} (${openCount} open)`);\\n    }\\n  }\\n  field('created', task.created_at);\\n  field('updated', task.updated_at);\\n  if (task.completed_at) field('completed', task.completed_at);\\n  if (task.note) {\\n    lines.push('');\\n    lines.push(`  ${styles.dim('note:')}`);\\n    for (const line of String(task.note).split('\\\\n')) lines.push(`    ${line}`);\\n  }\\n\\n  if (db) {\\n    const kids = db.tasks.filter((t) => t.parent === task.id);\\n    if (kids.length) {\\n      lines.push('');\\n      lines.push(renderTable(kids.map((t) => ({ task: t, depth: 0 })), opts)\\n        .split('\\\\n').map((l) => '  ' + l).join('\\\\n'));\\n    }\\n  }\\n\\n  return lines.join('\\\\n');\\n}\\n\\nmodule.exports = {\\n  colorEnabled, makeStyles, stripAnsi, width, pad, truncate,\\n  renderTable, renderDetail, statusGlyph, priorityLabel,\\n};\\n\"},{\"path\":\"src/store.js\",\"bytes\":3879,\"text\":\"'use strict';\\n\\nconst fs = require('fs');\\nconst os = require('os');\\nconst path = require('path');\\n\\nconst { AppError } = require('./errors.js');\\n\\nconst SCHEMA_VERSION = 1;\\n\\n/**\\n * Where the task file lives, in precedence order:\\n *   1. --file <path>\\n *   2. $TODO_FILE\\n *   3. $XDG_DATA_HOME/todo/todos.json\\n *   4. platform default: ~/.local/share/todo/todos.json\\n *      (%LOCALAPPDATA%\\\\todo\\\\todos.json on Windows)\\n */\\nfunction resolvePath(explicit, env = process.env) {\\n  if (explicit) return path.resolve(explicit);\\n  if (env.TODO_FILE) return path.resolve(env.TODO_FILE);\\n  if (env.XDG_DATA_HOME) return path.join(path.resolve(env.XDG_DATA_HOME), 'todo', 'todos.json');\\n  if (process.platform === 'win32' && (env.LOCALAPPDATA || env.APPDATA)) {\\n    return path.join(env.LOCALAPPDATA || env.APPDATA, 'todo', 'todos.json');\\n  }\\n  return path.join(os.homedir(), '.local', 'share', 'todo', 'todos.json');\\n}\\n\\nfunction emptyDb() {\\n  return { version: SCHEMA_VERSION, nextId: 1, tasks: [] };\\n}\\n\\nfunction load(file) {\\n  let raw;\\n  try {\\n    raw = fs.readFileSync(file, 'utf8');\\n  } catch (err) {\\n    if (err.code === 'ENOENT') return emptyDb();\\n    if (err.code === 'EACCES' || err.code === 'EPERM') {\\n      throw new AppError(`cannot read ${file}: permission denied`, { code: 'io' });\\n    }\\n    throw new AppError(`cannot read ${file}: ${err.message}`, { code: 'io' });\\n  }\\n\\n  if (raw.trim() === '') return emptyDb();\\n\\n  let db;\\n  try {\\n    db = JSON.parse(raw);\\n  } catch (err) {\\n    throw new AppError(`task file is not valid JSON: ${file}`, {\\n      code: 'corrupt',\\n      hint: `parse error: ${err.message}`,\\n    });\\n  }\\n\\n  if (!db || typeof db !== 'object' || !Array.isArray(db.tasks)) {\\n    throw new AppError(`task file has an unexpected shape: ${file}`, { code: 'corrupt' });\\n  }\\n  if (typeof db.version === 'number' && db.version > SCHEMA_VERSION) {\\n    throw new AppError(\\n      `task file was written by a newer version (schema ${db.version}, this build understands ${SCHEMA_VERSION})`,\\n      { code: 'corrupt' }\\n    );\\n  }\\n\\n  db.version = SCHEMA_VERSION;\\n  const maxId = db.tasks.reduce((m, t) => Math.max(m, Number(t && t.id) || 0), 0);\\n  // nextId is authoritative; the max-id floor only guards a hand-edited file.\\n  db.nextId = Math.max(Number(db.nextId) || 1, maxId + 1);\\n  return db;\\n}\\n\\n/**\\n * Write the whole store atomically: full contents into a sibling temp file,\\n * flushed to disk, then renamed over the target. A crash leaves either the\\n * old file or the new one — never a half-written one.\\n */\\nfunction save(file, db) {\\n  const dir = path.dirname(file);\\n  try {\\n    fs.mkdirSync(dir, { recursive: true });\\n  } catch (err) {\\n    throw new AppError(`cannot create ${dir}: ${err.message}`, { code: 'io' });\\n  }\\n\\n  const payload = JSON.stringify(db, null, 2) + '\\\\n';\\n  const tmp = path.join(dir, `.${path.basename(file)}.${process.pid}.${Date.now().toString(36)}.tmp`);\\n\\n  let fd;\\n  try {\\n    fd = fs.openSync(tmp, 'wx', 0o600);\\n    fs.writeFileSync(fd, payload, 'utf8');\\n    fs.fsyncSync(fd);\\n  } catch (err) {\\n    try { if (fd !== undefined) fs.closeSync(fd); } catch { /* already closed */ }\\n    try { fs.unlinkSync(tmp); } catch { /* nothing to clean up */ }\\n    throw new AppError(`cannot write ${file}: ${err.message}`, { code: 'io' });\\n  }\\n  try { fs.closeSync(fd); } catch { /* already closed */ }\\n\\n  try {\\n    fs.renameSync(tmp, file);\\n  } catch (err) {\\n    try { fs.unlinkSync(tmp); } catch { /* nothing to clean up */ }\\n    throw new AppError(`cannot replace ${file}: ${err.message}`, { code: 'io' });\\n  }\\n\\n  // Best effort: make the rename itself durable. Not supported everywhere.\\n  try {\\n    const dfd = fs.openSync(dir, 'r');\\n    try { fs.fsyncSync(dfd); } finally { fs.closeSync(dfd); }\\n  } catch { /* directory fsync is unavailable on Windows and some filesystems */ }\\n}\\n\\nmodule.exports = { resolvePath, load, save, emptyDb, SCHEMA_VERSION };\\n\"},{\"path\":\"test/cli.test.js\",\"bytes\":20314,\"text\":\"'use strict';\\n\\nconst test = require('node:test');\\nconst assert = require('node:assert');\\nconst { spawnSync } = require('node:child_process');\\nconst fs = require('node:fs');\\nconst os = require('node:os');\\nconst path = require('node:path');\\n\\nconst BIN = path.join(__dirname, '..', 'bin', 'todo.js');\\n\\nfunction makeStore() {\\n  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'todo-test-'));\\n  return path.join(dir, 'todos.json');\\n}\\n\\n/** Run the CLI against a given store. Stdin is a closed pipe unless supplied. */\\nfunction todo(file, args, { input = '', env = {} } = {}) {\\n  const r = spawnSync(process.execPath, [BIN, '--file', file, ...args], {\\n    input,\\n    encoding: 'utf8',\\n    env: { ...process.env, NO_COLOR: '', TODO_FILE: '', ...env },\\n  });\\n  return { code: r.status, out: r.stdout, err: r.stderr };\\n}\\n\\nfunction addTask(file, ...args) {\\n  const r = todo(file, ['add', ...args]);\\n  assert.strictEqual(r.code, 0, r.err);\\n  return Number(r.out.trim());\\n}\\n\\n// ---------------------------------------------------------------------------\\n\\ntest('add returns the new id and list shows it', () => {\\n  const file = makeStore();\\n  const id = addTask(file, 'buy milk');\\n  assert.strictEqual(id, 1);\\n\\n  const list = todo(file, ['list']);\\n  assert.strictEqual(list.code, 0);\\n  assert.match(list.out, /buy milk/);\\n  assert.match(list.out, /\\\\[ \\\\]/);\\n});\\n\\ntest('add accepts unquoted multi-word titles', () => {\\n  const file = makeStore();\\n  addTask(file, 'buy', 'more', 'milk');\\n  const r = todo(file, ['list', '--json']);\\n  assert.strictEqual(JSON.parse(r.out)[0].title, 'buy more milk');\\n});\\n\\ntest('ids are not reused after deletion', () => {\\n  const file = makeStore();\\n  addTask(file, 'one');\\n  const two = addTask(file, 'two');\\n  assert.strictEqual(todo(file, ['delete', String(two), '--force']).code, 0);\\n  const three = addTask(file, 'three');\\n  assert.strictEqual(three, 3, 'the deleted id must not come back');\\n});\\n\\ntest('ids survive deletion of an earlier task', () => {\\n  const file = makeStore();\\n  const a = addTask(file, 'a');\\n  const b = addTask(file, 'b');\\n  todo(file, ['delete', String(a), '--force']);\\n  const json = JSON.parse(todo(file, ['list', '--json']).out);\\n  assert.deepStrictEqual(json.map((t) => t.id), [b]);\\n});\\n\\ntest('complete and reopen a task', () => {\\n  const file = makeStore();\\n  const id = addTask(file, 'ship it');\\n\\n  assert.strictEqual(todo(file, ['done', String(id)]).code, 0);\\n  let json = JSON.parse(todo(file, ['show', String(id), '--json']).out);\\n  assert.strictEqual(json.done, true);\\n  assert.ok(json.completed_at, 'completed_at is stamped');\\n  assert.strictEqual(todo(file, ['list']).out.includes('ship it'), false, 'done tasks are hidden by default');\\n  assert.match(todo(file, ['list', '--done']).out, /ship it/);\\n\\n  assert.strictEqual(todo(file, ['reopen', String(id)]).code, 0);\\n  json = JSON.parse(todo(file, ['show', String(id), '--json']).out);\\n  assert.strictEqual(json.done, false);\\n  assert.strictEqual(json.completed_at, null);\\n});\\n\\ntest('done on an already-done task is not an error', () => {\\n  const file = makeStore();\\n  const id = addTask(file, 'x');\\n  todo(file, ['done', String(id)]);\\n  const r = todo(file, ['done', String(id)]);\\n  assert.strictEqual(r.code, 0);\\n  assert.match(r.err, /already done/);\\n});\\n\\ntest('edit changes fields', () => {\\n  const file = makeStore();\\n  const id = addTask(file, 'draft', '--tag', 'old');\\n  const r = todo(file, ['edit', String(id), '--title', 'final', '--priority', 'high',\\n    '--due', '2030-01-02', '--project', 'web', '--add-tag', 'new', '--remove-tag', 'old']);\\n  assert.strictEqual(r.code, 0, r.err);\\n\\n  const t = JSON.parse(todo(file, ['show', String(id), '--json']).out);\\n  assert.strictEqual(t.title, 'final');\\n  assert.strictEqual(t.priority, 'high');\\n  assert.strictEqual(t.due, '2030-01-02');\\n  assert.strictEqual(t.project, 'web');\\n  assert.deepStrictEqual(t.tags, ['new']);\\n});\\n\\ntest('edit with nothing to change is a usage error', () => {\\n  const file = makeStore();\\n  const id = addTask(file, 'x');\\n  assert.strictEqual(todo(file, ['edit', String(id)]).code, 2);\\n});\\n\\ntest('edit can clear priority, due, project and note', () => {\\n  const file = makeStore();\\n  const id = addTask(file, 'x', '-p', 'high', '-d', '2030-01-01', '-P', 'web', '-n', 'hello');\\n  todo(file, ['edit', String(id), '--priority', 'none', '--due', 'none', '--project', 'none', '--note', '']);\\n  const t = JSON.parse(todo(file, ['show', String(id), '--json']).out);\\n  assert.strictEqual(t.priority, null);\\n  assert.strictEqual(t.due, null);\\n  assert.strictEqual(t.project, null);\\n  assert.strictEqual(t.note, null);\\n});\\n\\ntest('delete refuses without a terminal unless forced', () => {\\n  const file = makeStore();\\n  const id = addTask(file, 'precious');\\n  const refused = todo(file, ['delete', String(id)]);\\n  assert.strictEqual(refused.code, 2);\\n  assert.match(refused.err, /--force/);\\n  assert.strictEqual(JSON.parse(todo(file, ['list', '--json']).out).length, 1, 'nothing was deleted');\\n\\n  assert.strictEqual(todo(file, ['delete', String(id), '--force']).code, 0);\\n  assert.strictEqual(JSON.parse(todo(file, ['list', '--json']).out).length, 0);\\n});\\n\\ntest('deleting a parent lifts its sub-tasks unless --recursive', () => {\\n  const file = makeStore();\\n  const parent = addTask(file, 'parent');\\n  const child = addTask(file, 'child', '--parent', String(parent));\\n\\n  todo(file, ['delete', String(parent), '--force']);\\n  const t = JSON.parse(todo(file, ['show', String(child), '--json']).out);\\n  assert.strictEqual(t.parent, null);\\n\\n  const p2 = addTask(file, 'p2');\\n  const c2 = addTask(file, 'c2', '--parent', String(p2));\\n  todo(file, ['delete', String(p2), '--recursive', '--force']);\\n  assert.strictEqual(todo(file, ['show', String(c2)]).code, 1);\\n});\\n\\n// --- filters ---------------------------------------------------------------\\n\\ntest('filters: tag, priority, project, search', () => {\\n  const file = makeStore();\\n  addTask(file, 'work thing', '--tag', 'work', '-p', 'high', '-P', 'acme');\\n  addTask(file, 'home thing', '--tag', 'home', '-p', 'low');\\n  addTask(file, 'both', '--tag', 'work,home');\\n\\n  const titles = (args) => JSON.parse(todo(file, ['list', '--json', ...args]).out).map((t) => t.title);\\n\\n  assert.deepStrictEqual(titles(['--tag', 'work']).sort(), ['both', 'work thing']);\\n  assert.deepStrictEqual(titles(['--tag', 'work', '--tag', 'home']), ['both']);\\n  assert.deepStrictEqual(titles(['--any-tag', 'home']).sort(), ['both', 'home thing']);\\n  assert.deepStrictEqual(titles(['-p', 'high']), ['work thing']);\\n  assert.deepStrictEqual(titles(['-p', 'none']), ['both']);\\n  assert.deepStrictEqual(titles(['-P', 'acme']), ['work thing']);\\n  assert.deepStrictEqual(titles(['--search', 'home']).sort(), ['both', 'home thing']);\\n});\\n\\ntest('filters: --due today / overdue / none', () => {\\n  const file = makeStore();\\n  addTask(file, 'today thing', '--due', 'today');\\n  addTask(file, 'tomorrow thing', '--due', 'tomorrow');\\n  addTask(file, 'late thing', '--due', 'yesterday');\\n  addTask(file, 'no date');\\n\\n  const titles = (args) => JSON.parse(todo(file, ['list', '--json', ...args]).out).map((t) => t.title);\\n  assert.deepStrictEqual(titles(['--due', 'today']), ['today thing']);\\n  assert.deepStrictEqual(titles(['--due', 'overdue']), ['late thing']);\\n  assert.deepStrictEqual(titles(['--overdue']), ['late thing']);\\n  assert.deepStrictEqual(titles(['--due', 'none']), ['no date']);\\n  assert.deepStrictEqual(titles(['--due', 'week']).sort(), ['late thing', 'today thing', 'tomorrow thing']);\\n});\\n\\ntest('sub-tasks are indented under their parent', () => {\\n  const file = makeStore();\\n  const parent = addTask(file, 'parent task');\\n  addTask(file, 'child task', '--parent', String(parent));\\n  const lines = todo(file, ['list']).out.split('\\\\n');\\n  const childLine = lines.find((l) => l.includes('child task'));\\n  assert.match(childLine, /- child task/);\\n  assert.ok(lines.indexOf(childLine) > lines.findIndex((l) => l.includes('parent task')));\\n});\\n\\ntest('a sub-task cannot become its own ancestor', () => {\\n  const file = makeStore();\\n  const a = addTask(file, 'a');\\n  const b = addTask(file, 'b', '--parent', String(a));\\n  const r = todo(file, ['edit', String(a), '--parent', String(b)]);\\n  assert.strictEqual(r.code, 2);\\n  assert.match(r.err, /loop/);\\n});\\n\\n// --- output ----------------------------------------------------------------\\n\\ntest('--json emits stable field names', () => {\\n  const file = makeStore();\\n  addTask(file, 'x', '--tag', 'a', '-p', 'high', '-d', '2030-05-06', '-P', 'proj', '-n', 'note text');\\n  const [t] = JSON.parse(todo(file, ['list', '--json']).out);\\n  assert.deepStrictEqual(Object.keys(t), [\\n    'id', 'title', 'done', 'priority', 'due', 'tags', 'project', 'parent',\\n    'note', 'created_at', 'updated_at', 'completed_at',\\n  ]);\\n});\\n\\ntest('no colour when output is piped, even with --color plus NO_COLOR', () => {\\n  const file = makeStore();\\n  addTask(file, 'x', '-p', 'high');\\n  const piped = todo(file, ['list']);\\n  assert.ok(!piped.out.includes('\\u001b['), 'piped output is plain');\\n\\n  const forced = todo(file, ['--color', 'list']);\\n  assert.ok(forced.out.includes('\\u001b['), '--color forces colour on');\\n\\n  const suppressed = todo(file, ['--color', 'list'], { env: { NO_COLOR: '1' } });\\n  assert.ok(!suppressed.out.includes('\\u001b['), 'NO_COLOR beats --color');\\n\\n  const flagged = todo(file, ['--color', '--no-color', 'list']);\\n  assert.ok(!flagged.out.includes('\\u001b['), '--no-color beats --color');\\n});\\n\\ntest('--json output never contains colour', () => {\\n  const file = makeStore();\\n  addTask(file, 'x', '-p', 'high');\\n  const r = todo(file, ['--color', 'list', '--json']);\\n  assert.ok(!r.out.includes('\\u001b['));\\n  JSON.parse(r.out);\\n});\\n\\ntest('table columns are aligned', () => {\\n  const file = makeStore();\\n  addTask(file, 'short');\\n  addTask(file, 'a much longer title here');\\n  const lines = todo(file, ['list']).out.trim().split('\\\\n');\\n  const titleCol = lines[0].indexOf('TITLE');\\n  for (const line of lines.slice(1)) {\\n    assert.strictEqual(line.slice(titleCol, titleCol + 1) === ' ', false, `row not aligned: ${line}`);\\n  }\\n});\\n\\n// --- exit codes ------------------------------------------------------------\\n\\ntest('exit codes: 0 success, 1 not found, 2 usage', () => {\\n  const file = makeStore();\\n  addTask(file, 'x');\\n\\n  assert.strictEqual(todo(file, ['list']).code, 0);\\n\\n  const missing = todo(file, ['show', '999']);\\n  assert.strictEqual(missing.code, 1);\\n  assert.match(missing.err, /no task with id 999/);\\n  assert.ok(!missing.err.includes('at Object'), 'not-found is not a crash');\\n\\n  assert.strictEqual(todo(file, ['done', '999']).code, 1);\\n  assert.strictEqual(todo(file, ['delete', '999', '--force']).code, 1);\\n  assert.strictEqual(todo(file, ['edit', '999', '--title', 'y']).code, 1);\\n\\n  assert.strictEqual(todo(file, ['nonsense']).code, 2);\\n  assert.strictEqual(todo(file, ['list', '--nope']).code, 2);\\n  assert.strictEqual(todo(file, ['add', 'x', '-p', 'bogus']).code, 2);\\n  assert.strictEqual(todo(file, ['add', 'x', '-d', 'not-a-date']).code, 2);\\n  assert.strictEqual(todo(file, ['show', 'abc']).code, 2);\\n});\\n\\ntest('a missing id does not stop the ids that do exist', () => {\\n  const file = makeStore();\\n  const a = addTask(file, 'a');\\n  const r = todo(file, ['done', String(a), '999']);\\n  assert.strictEqual(r.code, 1);\\n  assert.strictEqual(JSON.parse(todo(file, ['show', String(a), '--json']).out).done, true);\\n});\\n\\ntest('--json reports errors as JSON on stderr', () => {\\n  const file = makeStore();\\n  const r = todo(file, ['show', '999', '--json']);\\n  assert.strictEqual(r.code, 1);\\n  assert.strictEqual(r.out, '');\\n  const payload = JSON.parse(r.err);\\n  assert.strictEqual(payload.error.code, 'not_found');\\n});\\n\\n// --- storage ---------------------------------------------------------------\\n\\ntest('the store is created on demand and is valid JSON', () => {\\n  const file = makeStore();\\n  assert.ok(!fs.existsSync(file));\\n  addTask(file, 'x');\\n  const db = JSON.parse(fs.readFileSync(file, 'utf8'));\\n  assert.strictEqual(db.version, 1);\\n  assert.strictEqual(db.nextId, 2);\\n  assert.strictEqual(db.tasks.length, 1);\\n});\\n\\ntest('listing a store that does not exist is not an error', () => {\\n  const file = makeStore();\\n  const r = todo(file, ['list']);\\n  assert.strictEqual(r.code, 0);\\n  assert.strictEqual(r.out, '');\\n  assert.strictEqual(todo(file, ['list', '--json']).out.trim(), '[]');\\n});\\n\\ntest('a corrupt store fails cleanly with exit 1', () => {\\n  const file = makeStore();\\n  fs.mkdirSync(path.dirname(file), { recursive: true });\\n  fs.writeFileSync(file, '{not json');\\n  const r = todo(file, ['list']);\\n  assert.strictEqual(r.code, 1);\\n  assert.match(r.err, /not valid JSON/);\\n});\\n\\ntest('writes leave no temp files behind', () => {\\n  const file = makeStore();\\n  addTask(file, 'x');\\n  addTask(file, 'y');\\n  const leftovers = fs.readdirSync(path.dirname(file)).filter((f) => f !== 'todos.json');\\n  assert.deepStrictEqual(leftovers, []);\\n});\\n\\ntest('a write never leaves a truncated file', () => {\\n  // Interleave many writers on one store; every intermediate state a reader\\n  // sees must be complete JSON, because writes land via rename.\\n  const file = makeStore();\\n  addTask(file, 'seed');\\n  for (let i = 0; i < 25; i++) {\\n    todo(file, ['add', `task ${i}`]);\\n    const raw = fs.readFileSync(file, 'utf8');\\n    assert.doesNotThrow(() => JSON.parse(raw), `store was mid-write at iteration ${i}`);\\n  }\\n});\\n\\ntest('XDG_DATA_HOME is respected', () => {\\n  const home = fs.mkdtempSync(path.join(os.tmpdir(), 'todo-xdg-'));\\n  const r = spawnSync(process.execPath, [BIN, 'add', 'xdg task'], {\\n    encoding: 'utf8',\\n    input: '',\\n    env: { ...process.env, XDG_DATA_HOME: home, TODO_FILE: '' },\\n  });\\n  assert.strictEqual(r.status, 0, r.stderr);\\n  assert.ok(fs.existsSync(path.join(home, 'todo', 'todos.json')));\\n});\\n\\ntest('TODO_FILE is respected and --file wins over it', () => {\\n  const a = makeStore();\\n  const b = makeStore();\\n  let r = spawnSync(process.execPath, [BIN, 'add', 'from env'], {\\n    encoding: 'utf8', input: '', env: { ...process.env, TODO_FILE: a },\\n  });\\n  assert.strictEqual(r.status, 0, r.stderr);\\n  assert.ok(fs.existsSync(a));\\n\\n  r = spawnSync(process.execPath, [BIN, '--file', b, 'add', 'from flag'], {\\n    encoding: 'utf8', input: '', env: { ...process.env, TODO_FILE: a },\\n  });\\n  assert.strictEqual(r.status, 0, r.stderr);\\n  assert.strictEqual(JSON.parse(fs.readFileSync(a, 'utf8')).tasks.length, 1);\\n  assert.strictEqual(JSON.parse(fs.readFileSync(b, 'utf8')).tasks[0].title, 'from flag');\\n});\\n\\n// --- stdin -----------------------------------------------------------------\\n\\ntest('bulk add reads stdin, one task per line', () => {\\n  const file = makeStore();\\n  const r = todo(file, ['add', '--tag', 'inbox'], { input: 'alpha\\\\nbeta\\\\n\\\\ngamma\\\\n' });\\n  assert.strictEqual(r.code, 0, r.err);\\n  assert.deepStrictEqual(r.out.trim().split('\\\\n'), ['1', '2', '3']);\\n\\n  const tasks = JSON.parse(todo(file, ['list', '--json']).out);\\n  assert.deepStrictEqual(tasks.map((t) => t.title).sort(), ['alpha', 'beta', 'gamma']);\\n  for (const t of tasks) assert.deepStrictEqual(t.tags, ['inbox']);\\n});\\n\\ntest('empty stdin for add is a usage error', () => {\\n  const file = makeStore();\\n  assert.strictEqual(todo(file, ['add'], { input: '' }).code, 2);\\n});\\n\\ntest('--parse pulls inline tokens out of the title', () => {\\n  const file = makeStore();\\n  todo(file, ['add', '--parse', 'fix login +bug @web !high due:2030-03-04']);\\n  const [t] = JSON.parse(todo(file, ['list', '--json']).out);\\n  assert.strictEqual(t.title, 'fix login');\\n  assert.deepStrictEqual(t.tags, ['bug']);\\n  assert.strictEqual(t.project, 'web');\\n  assert.strictEqual(t.priority, 'high');\\n  assert.strictEqual(t.due, '2030-03-04');\\n});\\n\\ntest('a plain title is never mangled without --parse', () => {\\n  const file = makeStore();\\n  todo(file, ['add', 'email @bob about c++ !!']);\\n  const [t] = JSON.parse(todo(file, ['list', '--json']).out);\\n  assert.strictEqual(t.title, 'email @bob about c++ !!');\\n  assert.deepStrictEqual(t.tags, []);\\n});\\n\\n// --- help & completion -----------------------------------------------------\\n\\ntest('--help works on every command and shows examples', () => {\\n  const file = makeStore();\\n  const commands = ['add', 'list', 'show', 'done', 'reopen', 'edit', 'delete', 'tags', 'projects', 'completion', 'help'];\\n  for (const c of commands) {\\n    const r = todo(file, [c, '--help']);\\n    assert.strictEqual(r.code, 0, `${c} --help failed: ${r.err}`);\\n    assert.match(r.out, /USAGE/, `${c} --help has no usage`);\\n    assert.match(r.out, /EXAMPLES/, `${c} --help has no examples`);\\n  }\\n  const root = todo(file, ['--help']);\\n  assert.strictEqual(root.code, 0);\\n  assert.match(root.out, /EXAMPLES/);\\n  assert.match(root.out, /EXIT CODES/);\\n});\\n\\ntest('help <command> matches <command> --help', () => {\\n  const file = makeStore();\\n  assert.strictEqual(todo(file, ['help', 'add']).out, todo(file, ['add', '--help']).out);\\n});\\n\\ntest('completion scripts are produced for bash, zsh and fish', () => {\\n  const file = makeStore();\\n  const bash = todo(file, ['completion', 'bash']);\\n  assert.strictEqual(bash.code, 0);\\n  assert.match(bash.out, /complete -F _todo todo/);\\n\\n  const zsh = todo(file, ['completion', 'zsh']);\\n  assert.strictEqual(zsh.code, 0);\\n  assert.match(zsh.out, /#compdef todo/);\\n\\n  const fish = todo(file, ['completion', 'fish']);\\n  assert.strictEqual(fish.code, 0);\\n  assert.match(fish.out, /complete -c todo/);\\n\\n  assert.strictEqual(todo(file, ['completion', 'powershell']).code, 2);\\n  assert.strictEqual(todo(file, ['completion']).code, 2);\\n});\\n\\ntest('the completion helper lists ids, tags and projects', () => {\\n  const file = makeStore();\\n  const a = addTask(file, 'alpha', '--tag', 'work', '-P', 'acme');\\n  const b = addTask(file, 'beta');\\n  todo(file, ['done', String(b)]);\\n\\n  assert.deepStrictEqual(todo(file, ['__complete', 'ids']).out.trim().split('\\\\n'), [String(a)]);\\n  assert.deepStrictEqual(todo(file, ['__complete', 'done-ids']).out.trim().split('\\\\n'), [String(b)]);\\n  assert.deepStrictEqual(todo(file, ['__complete', 'all-ids']).out.trim().split('\\\\n'), [String(a), String(b)]);\\n  assert.strictEqual(todo(file, ['__complete', 'tags']).out.trim(), 'work');\\n  assert.strictEqual(todo(file, ['__complete', 'projects']).out.trim(), 'acme');\\n  assert.match(todo(file, ['__complete', 'all-ids-zsh']).out, /^1:alpha$/m);\\n});\\n\\ntest('tags and projects report counts', () => {\\n  const file = makeStore();\\n  addTask(file, 'a', '--tag', 'work', '-P', 'acme');\\n  addTask(file, 'b', '--tag', 'work');\\n  assert.deepStrictEqual(JSON.parse(todo(file, ['tags', '--json']).out), [{ tag: 'work', count: 2 }]);\\n  assert.deepStrictEqual(JSON.parse(todo(file, ['projects', '--json']).out), [{ project: 'acme', count: 1 }]);\\n});\\n\\ntest('aliases work', () => {\\n  const file = makeStore();\\n  const id = addTask(file, 'x');\\n  assert.strictEqual(todo(file, ['ls']).code, 0);\\n  assert.strictEqual(todo(file, ['complete', String(id)]).code, 0);\\n  assert.strictEqual(todo(file, ['undone', String(id)]).code, 0);\\n  assert.strictEqual(todo(file, ['rm', String(id), '-f']).code, 0);\\n});\\n\\ntest('--version prints a version', () => {\\n  const file = makeStore();\\n  assert.match(todo(file, ['--version']).out.trim(), /^\\\\d+\\\\.\\\\d+\\\\.\\\\d+$/);\\n});\\n\\ntest('--limit, --sort and --ids', () => {\\n  const file = makeStore();\\n  addTask(file, 'c', '-d', '2030-03-03');\\n  addTask(file, 'a', '-d', '2030-01-01');\\n  addTask(file, 'b', '-d', '2030-02-02');\\n\\n  const ids = todo(file, ['list', '--ids', '--sort', 'due']).out.trim().split('\\\\n');\\n  assert.deepStrictEqual(ids, ['2', '3', '1']);\\n  assert.deepStrictEqual(todo(file, ['list', '--ids', '--sort', 'due', '--reverse']).out.trim().split('\\\\n'), ['1', '3', '2']);\\n  assert.deepStrictEqual(todo(file, ['list', '--ids', '--sort', 'title', '--limit', '2']).out.trim().split('\\\\n'), ['2', '3']);\\n  assert.strictEqual(todo(file, ['list', '--sort', 'bogus']).code, 2);\\n  assert.strictEqual(todo(file, ['list', '--limit', 'x']).code, 2);\\n});\\n\\ntest('done --recursive completes the whole subtree', () => {\\n  const file = makeStore();\\n  const p = addTask(file, 'parent');\\n  const c = addTask(file, 'child', '--parent', String(p));\\n  const gc = addTask(file, 'grandchild', '--parent', String(c));\\n\\n  todo(file, ['done', String(p), '--recursive']);\\n  for (const id of [p, c, gc]) {\\n    assert.strictEqual(JSON.parse(todo(file, ['show', String(id), '--json']).out).done, true);\\n  }\\n});\\n\"},{\"path\":\"test/completion.test.js\",\"bytes\":3872,\"text\":\"'use strict';\\n\\n// Exercises the generated bash completion for real, if bash is available.\\n// zsh and fish are syntax-shaped for their own shells and cannot be run here.\\n\\nconst test = require('node:test');\\nconst assert = require('node:assert');\\nconst { spawnSync } = require('node:child_process');\\nconst fs = require('node:fs');\\nconst os = require('node:os');\\nconst path = require('node:path');\\n\\nconst ROOT = path.join(__dirname, '..');\\nconst BIN = path.join(ROOT, 'bin', 'todo.js');\\n\\nconst bashAvailable = !spawnSync('bash', ['--version'], { encoding: 'utf8' }).error;\\n\\nfunction toPosix(p) {\\n  const win = /^([A-Za-z]):[\\\\\\\\/](.*)$/.exec(p);\\n  const norm = win ? `/${win[1].toLowerCase()}/${win[2]}` : p;\\n  return norm.split('\\\\\\\\').join('/');\\n}\\n\\n/** Ask the completion function what it would suggest for a command line. */\\nfunction complete(store, words, cword) {\\n  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'todo-comp-'));\\n  const shim = path.join(dir, 'todo');\\n  fs.writeFileSync(\\n    shim,\\n    `#!/bin/sh\\\\nexec \\\"${toPosix(process.execPath)}\\\" \\\"${toPosix(BIN)}\\\" --file \\\"${toPosix(store)}\\\" \\\"$@\\\"\\\\n`,\\n    { mode: 0o755 }\\n  );\\n\\n  const script = `\\n    export PATH=\\\"${toPosix(dir)}:$PATH\\\"\\n    source \\\"${toPosix(path.join(ROOT, 'completions', 'todo.bash'))}\\\"\\n    COMP_WORDS=(${words.map((w) => `'${w}'`).join(' ')})\\n    COMP_CWORD=${cword}\\n    _todo\\n    printf '%s\\\\\\\\n' \\\"\\\\${COMPREPLY[@]}\\\"\\n  `;\\n  const r = spawnSync('bash', ['-c', script], { encoding: 'utf8' });\\n  assert.strictEqual(r.status, 0, r.stderr);\\n  return r.stdout.split('\\\\n').map((s) => s.trim()).filter(Boolean);\\n}\\n\\ntest('bash completion suggests commands, options and live data', { skip: !bashAvailable && 'bash not installed' }, () => {\\n  const store = path.join(fs.mkdtempSync(path.join(os.tmpdir(), 'todo-comp-store-')), 'todos.json');\\n  const run = (...args) => spawnSync(process.execPath, [BIN, '--file', store, ...args], { encoding: 'utf8', input: '' });\\n  run('add', 'alpha', '--tag', 'work', '--project', 'acme');\\n  run('add', 'beta', '--tag', 'home');\\n\\n  assert.ok(complete(store, ['todo', ''], 1).includes('list'), 'commands are offered');\\n  assert.ok(complete(store, ['todo', 'l'], 1).includes('list'));\\n\\n  const listOpts = complete(store, ['todo', 'list', '--'], 2);\\n  assert.ok(listOpts.includes('--overdue'), 'list options are offered');\\n  assert.ok(listOpts.includes('--json'), 'global options are offered too');\\n\\n  assert.deepStrictEqual(complete(store, ['todo', 'list', '--tag', ''], 3).sort(), ['home', 'work']);\\n  assert.deepStrictEqual(complete(store, ['todo', 'list', '--project', ''], 3).sort(), ['acme', 'none']);\\n  assert.deepStrictEqual(complete(store, ['todo', 'done', ''], 2).sort(), ['1', '2']);\\n  assert.ok(complete(store, ['todo', 'list', '--priority', ''], 3).includes('high'));\\n  assert.deepStrictEqual(complete(store, ['todo', 'completion', ''], 2).sort(), ['bash', 'fish', 'zsh']);\\n});\\n\\ntest('the zsh and fish scripts carry the markers their shells need', () => {\\n  const zsh = fs.readFileSync(path.join(ROOT, 'completions', 'todo.zsh'), 'utf8');\\n  assert.match(zsh, /^#compdef todo/);\\n  assert.match(zsh, /_describe -t commands/);\\n  assert.match(zsh, /__complete all-ids-zsh/);\\n\\n  const fish = fs.readFileSync(path.join(ROOT, 'completions', 'todo.fish'), 'utf8');\\n  assert.match(fish, /complete -c todo -n __todo_no_command -a add/);\\n  assert.match(fish, /__complete all-ids-fish/);\\n\\n  // The helper commands both scripts rely on must exist.\\n  const store = path.join(fs.mkdtempSync(path.join(os.tmpdir(), 'todo-comp-h-')), 'todos.json');\\n  for (const what of ['ids', 'all-ids', 'done-ids', 'ids-zsh', 'all-ids-zsh', 'all-ids-fish', 'tags', 'projects', 'commands']) {\\n    const r = spawnSync(process.execPath, [BIN, '--file', store, '__complete', what], { encoding: 'utf8', input: '' });\\n    assert.strictEqual(r.status, 0, `__complete ${what} failed: ${r.stderr}`);\\n  }\\n});\\n\"},{\"path\":\"test/helpers/as-tty.js\",\"bytes\":474,\"text\":\"'use strict';\\n\\n// Runs the CLI while claiming stdin and/or stdout are terminals, so the\\n// confirmation prompt and the colourised table can be tested from a script.\\n//   node as-tty.js <in|out|both> <args...>\\n\\nconst which = process.argv[2];\\nif (which === 'in' || which === 'both') process.stdin.isTTY = true;\\nif (which === 'out' || which === 'both') {\\n  process.stdout.isTTY = true;\\n  process.stdout.columns = 80;\\n}\\n\\nrequire('../../src/cli.js').main(process.argv.slice(3));\\n\"},{\"path\":\"test/tty.test.js\",\"bytes\":4268,\"text\":\"'use strict';\\n\\nconst test = require('node:test');\\nconst assert = require('node:assert');\\nconst { spawnSync } = require('node:child_process');\\nconst fs = require('node:fs');\\nconst os = require('node:os');\\nconst path = require('node:path');\\n\\nconst BIN = path.join(__dirname, '..', 'bin', 'todo.js');\\nconst AS_TTY = path.join(__dirname, 'helpers', 'as-tty.js');\\n\\nfunction makeStore() {\\n  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'todo-tty-'));\\n  return path.join(dir, 'todos.json');\\n}\\n\\nfunction todo(file, args, input = '') {\\n  const r = spawnSync(process.execPath, [BIN, '--file', file, ...args], {\\n    input, encoding: 'utf8', env: { ...process.env, TODO_FILE: '' },\\n  });\\n  return { code: r.status, out: r.stdout, err: r.stderr };\\n}\\n\\nfunction asTty(which, file, args, input = '') {\\n  const r = spawnSync(process.execPath, [AS_TTY, which, '--file', file, ...args], {\\n    input, encoding: 'utf8', env: { ...process.env, TODO_FILE: '', NO_COLOR: '' },\\n  });\\n  return { code: r.status, out: r.stdout, err: r.stderr };\\n}\\n\\nfunction add(file, ...args) {\\n  return Number(todo(file, ['add', ...args]).out.trim());\\n}\\n\\ntest('delete asks before removing, and \\\"n\\\" keeps the task', () => {\\n  const file = makeStore();\\n  const id = add(file, 'precious');\\n  const r = asTty('in', file, ['delete', String(id)], 'n\\\\n');\\n  assert.strictEqual(r.code, 1, 'a declined delete is a failure, not a success');\\n  assert.match(r.err, /Continue\\\\?/);\\n  assert.match(r.err, /cancelled/);\\n  assert.strictEqual(JSON.parse(todo(file, ['list', '--json']).out).length, 1);\\n});\\n\\ntest('delete asks before removing, and \\\"y\\\" removes it', () => {\\n  const file = makeStore();\\n  const id = add(file, 'goner');\\n  const r = asTty('in', file, ['delete', String(id)], 'y\\\\n');\\n  assert.strictEqual(r.code, 0, r.err);\\n  assert.match(r.err, /#1  goner/);\\n  assert.strictEqual(JSON.parse(todo(file, ['list', '--json']).out).length, 0);\\n});\\n\\ntest('an empty answer keeps the task', () => {\\n  const file = makeStore();\\n  const id = add(file, 'safe');\\n  assert.strictEqual(asTty('in', file, ['delete', String(id)], '\\\\n').code, 1);\\n  assert.strictEqual(JSON.parse(todo(file, ['list', '--json']).out).length, 1);\\n});\\n\\ntest('the prompt warns that sub-tasks will be lifted', () => {\\n  const file = makeStore();\\n  const p = add(file, 'parent');\\n  add(file, 'child', '--parent', String(p));\\n  const r = asTty('in', file, ['delete', String(p)], 'n\\\\n');\\n  assert.match(r.err, /sub-task .*top level/);\\n});\\n\\ntest('--force skips the prompt even on a terminal', () => {\\n  const file = makeStore();\\n  const id = add(file, 'x');\\n  const r = asTty('in', file, ['delete', String(id), '--force'], '');\\n  assert.strictEqual(r.code, 0);\\n  assert.ok(!r.err.includes('Continue?'));\\n});\\n\\ntest('the table is colourised on a terminal and plain when piped', () => {\\n  const file = makeStore();\\n  add(file, 'urgent thing', '-p', 'high', '-d', '2020-01-01', '--tag', 'work');\\n\\n  const tty = asTty('out', file, ['list']);\\n  assert.strictEqual(tty.code, 0, tty.err);\\n  assert.match(tty.out, /\\u001b\\\\[31m/, 'overdue dates and high priority are red');\\n  assert.match(tty.out, /\\u001b\\\\[36m/, 'tags are cyan');\\n\\n  const piped = todo(file, ['list']);\\n  assert.ok(!piped.out.includes('\\u001b['), 'piped output has no escapes');\\n  assert.strictEqual(piped.out.replace(/\\\\s+/g, ' '), tty.out.replace(/\\u001b\\\\[[0-9;]*m/g, '').replace(/\\\\s+/g, ' '));\\n});\\n\\ntest('NO_COLOR wins on a terminal too', () => {\\n  const file = makeStore();\\n  add(file, 'x', '-p', 'high');\\n  const r = spawnSync(process.execPath, [AS_TTY, 'out', '--file', file, 'list'], {\\n    input: '', encoding: 'utf8', env: { ...process.env, TODO_FILE: '', NO_COLOR: '1' },\\n  });\\n  assert.ok(!r.stdout.includes('\\u001b['));\\n});\\n\\ntest('titles are truncated to the terminal width', () => {\\n  const file = makeStore();\\n  add(file, 'y'.repeat(300));\\n  const r = asTty('out', file, ['--no-color', 'list']);\\n  for (const line of r.out.trim().split('\\\\n')) {\\n    assert.ok(line.length <= 80, `line is ${line.length} columns wide`);\\n  }\\n  assert.match(r.out, /…/, 'truncation is marked');\\n});\\n\\ntest('add on a terminal with no title explains itself instead of hanging', () => {\\n  const file = makeStore();\\n  const r = asTty('in', file, ['add'], '');\\n  assert.strictEqual(r.code, 2);\\n  assert.match(r.err, /needs a title/);\\n});\\n\"},{\"path\":\"test/unit.test.js\",\"bytes\":8099,\"text\":\"'use strict';\\n\\nconst test = require('node:test');\\nconst assert = require('node:assert');\\n\\nconst dates = require('../src/dates.js');\\nconst model = require('../src/model.js');\\nconst render = require('../src/render.js');\\nconst { parse } = require('../src/args.js');\\nconst { UsageError } = require('../src/errors.js');\\n\\nconst AT = new Date(2026, 7, 3);   // Monday 3 August 2026, local time\\n\\ntest('date parsing', () => {\\n  assert.strictEqual(dates.parseDue('today', AT), '2026-08-03');\\n  assert.strictEqual(dates.parseDue('tomorrow', AT), '2026-08-04');\\n  assert.strictEqual(dates.parseDue('yesterday', AT), '2026-08-02');\\n  assert.strictEqual(dates.parseDue('+3d', AT), '2026-08-06');\\n  assert.strictEqual(dates.parseDue('2w', AT), '2026-08-17');\\n  assert.strictEqual(dates.parseDue('1m', AT), '2026-09-03');\\n  assert.strictEqual(dates.parseDue('2026-12-25', AT), '2026-12-25');\\n  assert.strictEqual(dates.parseDue('friday', AT), '2026-08-07');\\n  assert.strictEqual(dates.parseDue('monday', AT), '2026-08-03', 'today counts as this weekday');\\n  assert.strictEqual(dates.parseDue('next monday', AT), '2026-08-10');\\n  assert.strictEqual(dates.parseDue('eom', AT), '2026-08-31');\\n  assert.strictEqual(dates.parseDue('none', AT), null);\\n  assert.throws(() => dates.parseDue('2026-02-31', AT), UsageError);\\n  assert.throws(() => dates.parseDue('sometime', AT), UsageError);\\n});\\n\\ntest('month arithmetic clamps to the end of a short month', () => {\\n  assert.strictEqual(dates.parseDue('1m', new Date(2026, 0, 31)), '2026-02-28');\\n});\\n\\ntest('relative labels', () => {\\n  assert.strictEqual(dates.relativeLabel('2026-08-03', AT), 'today');\\n  assert.strictEqual(dates.relativeLabel('2026-08-04', AT), 'tomorrow');\\n  assert.strictEqual(dates.relativeLabel('2026-08-02', AT), 'yesterday');\\n  assert.strictEqual(dates.relativeLabel('2026-07-30', AT), '4d ago');\\n  assert.strictEqual(dates.relativeLabel('2026-08-06', AT), 'in 3d');\\n});\\n\\ntest('priority aliases', () => {\\n  for (const s of ['high', 'H', 'hi', '1', 'urgent']) assert.strictEqual(model.parsePriority(s), 'high');\\n  for (const s of ['medium', 'm', 'med', '2', 'normal']) assert.strictEqual(model.parsePriority(s), 'medium');\\n  for (const s of ['low', 'l', '3']) assert.strictEqual(model.parsePriority(s), 'low');\\n  assert.strictEqual(model.parsePriority('none'), null);\\n  assert.throws(() => model.parsePriority('urgentish'), UsageError);\\n});\\n\\ntest('tag normalisation', () => {\\n  assert.deepStrictEqual(model.normalizeTags(['Work', '#work', '+WORK', 'home']), ['work', 'home']);\\n  assert.throws(() => model.normalizeTag('two words'), UsageError);\\n});\\n\\ntest('option parsing forms', () => {\\n  const spec = {\\n    flags: {\\n      tag: { type: 'array', short: 't' },\\n      due: { type: 'string', short: 'd' },\\n      force: { type: 'boolean', short: 'f' },\\n      json: { type: 'boolean' },\\n    },\\n  };\\n  let r = parse(['add', '--tag', 'a', '--tag=b', '-t', 'c,d', 'title'], spec);\\n  assert.deepStrictEqual(r.flags.tag, ['a', 'b', 'c', 'd']);\\n  assert.deepStrictEqual(r.positional, ['add', 'title']);\\n\\n  r = parse(['-fd', 'tomorrow'], spec);\\n  assert.strictEqual(r.flags.force, true);\\n  assert.strictEqual(r.flags.due, 'tomorrow');\\n\\n  r = parse(['--json=false'], spec);\\n  assert.strictEqual(r.flags.json, false);\\n\\n  r = parse(['--', '--not-a-flag'], spec);\\n  assert.deepStrictEqual(r.positional, ['--not-a-flag']);\\n\\n  assert.throws(() => parse(['--nope'], spec), UsageError);\\n  assert.throws(() => parse(['--due'], spec), UsageError);\\n});\\n\\ntest('ids come from a counter, never recycled', () => {\\n  const db = { version: 1, nextId: 1, tasks: [] };\\n  const a = model.createTask(db, { title: 'a' });\\n  const b = model.createTask(db, { title: 'b' });\\n  db.tasks = db.tasks.filter((t) => t.id !== b.id);\\n  const c = model.createTask(db, { title: 'c' });\\n  assert.deepStrictEqual([a.id, b.id, c.id], [1, 2, 3]);\\n});\\n\\ntest('cycle detection covers grandchildren', () => {\\n  const db = { version: 1, nextId: 1, tasks: [] };\\n  const a = model.createTask(db, { title: 'a' });\\n  const b = model.createTask(db, { title: 'b', parent: a.id });\\n  const c = model.createTask(db, { title: 'c', parent: b.id });\\n  assert.strictEqual(model.wouldCycle(db, a.id, c.id), true);\\n  assert.strictEqual(model.wouldCycle(db, a.id, a.id), true);\\n  assert.strictEqual(model.wouldCycle(db, c.id, a.id), false);\\n  assert.strictEqual(model.wouldCycle(db, a.id, null), false);\\n});\\n\\ntest('colour is decided by TTY, NO_COLOR and flags', () => {\\n  const tty = { isTTY: true };\\n  const pipe = { isTTY: false };\\n  assert.strictEqual(render.colorEnabled({ stream: tty, env: {} }), true);\\n  assert.strictEqual(render.colorEnabled({ stream: pipe, env: {} }), false);\\n  assert.strictEqual(render.colorEnabled({ stream: tty, env: { NO_COLOR: '1' } }), false);\\n  assert.strictEqual(render.colorEnabled({ stream: tty, env: { NO_COLOR: '' } }), true, 'empty NO_COLOR is ignored');\\n  assert.strictEqual(render.colorEnabled({ stream: tty, env: { TERM: 'dumb' } }), false);\\n  assert.strictEqual(render.colorEnabled({ stream: pipe, env: {}, forceColor: true }), true);\\n  assert.strictEqual(render.colorEnabled({ stream: tty, env: {}, noColor: true }), false);\\n  assert.strictEqual(render.colorEnabled({ stream: tty, env: {}, json: true }), false);\\n  assert.strictEqual(render.colorEnabled({ stream: pipe, env: { CLICOLOR_FORCE: '1' } }), true);\\n});\\n\\ntest('table alignment ignores escape sequences', () => {\\n  const styles = render.makeStyles(true);\\n  const db = { version: 1, nextId: 1, tasks: [] };\\n  model.createTask(db, { title: 'short', priority: 'high', tags: ['a'] });\\n  model.createTask(db, { title: 'a considerably longer title', tags: ['bbbbbb'] });\\n  const table = render.renderTable(db.tasks.map((t) => ({ task: t, depth: 0 })), { styles, now: AT });\\n  const lines = table.split('\\\\n').map(render.stripAnsi);\\n  const col = lines[0].indexOf('TITLE');\\n  assert.strictEqual(lines[1].slice(col), 'short');\\n  assert.strictEqual(lines[2].slice(col), 'a considerably longer title');\\n});\\n\\ntest('long titles are truncated to the terminal width', () => {\\n  const db = { version: 1, nextId: 1, tasks: [] };\\n  model.createTask(db, { title: 'x'.repeat(200) });\\n  const table = render.renderTable(db.tasks.map((t) => ({ task: t, depth: 0 })), { terminalWidth: 40 });\\n  for (const line of table.split('\\\\n')) assert.ok(line.length <= 40, `line too wide: ${line.length}`);\\n});\\n\\ntest('default sort puts open, high-priority, soonest-due first', () => {\\n  const db = { version: 1, nextId: 1, tasks: [] };\\n  const low = model.createTask(db, { title: 'low', priority: 'low' });\\n  const high = model.createTask(db, { title: 'high', priority: 'high' });\\n  const soon = model.createTask(db, { title: 'soon', due: '2026-08-04' });\\n  const finished = model.createTask(db, { title: 'finished' });\\n  finished.done = true;\\n\\n  const order = model.sortTasks(db.tasks, null, false).map((t) => t.title);\\n  assert.deepStrictEqual(order, ['high', 'low', 'soon', 'finished']);\\n  assert.ok(order.indexOf('finished') === order.length - 1);\\n  assert.ok([low, high, soon].every((t) => !t.done));\\n});\\n\\ntest('a filtered-out parent does not hide its child', () => {\\n  const db = { version: 1, nextId: 1, tasks: [] };\\n  const parent = model.createTask(db, { title: 'parent' });\\n  const child = model.createTask(db, { title: 'child', parent: parent.id, tags: ['x'] });\\n  const matched = model.filterTasks(db, { status: 'pending', tags: ['x'] });\\n  const rows = model.buildTree(matched, model.defaultComparator());\\n  assert.deepStrictEqual(rows, [{ task: child, depth: 0 }]);\\n});\\n\\ntest('due-range filters', () => {\\n  const db = { version: 1, nextId: 1, tasks: [] };\\n  model.createTask(db, { title: 'early', due: '2026-08-01' });\\n  model.createTask(db, { title: 'late', due: '2026-09-01' });\\n  const titles = (spec) => model.filterTasks(db, { status: 'pending', due: spec }, AT).map((t) => t.title);\\n  assert.deepStrictEqual(titles('before:2026-08-15'), ['early']);\\n  assert.deepStrictEqual(titles('after:2026-08-15'), ['late']);\\n  assert.deepStrictEqual(titles('on:2026-09-01'), ['late']);\\n  assert.deepStrictEqual(titles('overdue'), ['early']);\\n});\\n\"}]"),s={slug:n,selfReport:t,files:e};export{s as default,e as files,t as selfReport,n as slug};
